/* --- 15. AUTO-CRAWLER & COMPREHENSIVE DATA MODAL --- */
.btn-crawl-full {
  background: linear-gradient(135deg, #2563EB 0%, #1D4ED8 100%);
  color: #FFFFFF !important;
  border: 1.5px solid #1E40AF;
  padding: 8px 18px;
  border-radius: var(--r-pill);
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  box-shadow: 0 4px 14px rgba(37, 99, 235, 0.35);
  transition: all var(--dur-normal) var(--ease-out);
}

.btn-crawl-full:hover {
  background: linear-gradient(135deg, #1D4ED8 0%, #1E40AF 100%);
  transform: translateY(-1.5px);
  box-shadow: 0 6px 18px rgba(37, 99, 235, 0.45);
}

.data-volume-badge-wrapper {
  display: flex;
  align-items: center;
}

.data-volume-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #EFF6FF;
  border: 1px solid #BFDBFE;
  color: #1E40AF;
  font-size: 13px;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: var(--r-pill);
  box-shadow: 0 1px 3px rgba(37, 99, 235, 0.08);
}

.data-volume-badge strong,
.data-volume-badge b,
.data-volume-badge span {
  font-weight: 700;
  color: #1D4ED8;
}

/* Modal Overlay */
.crawl-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.65);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  animation: fadeIn 0.25s ease-out;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.crawl-modal-card {
  background: #FFFFFF;
  border: 1px solid var(--line-medium);
  border-radius: 20px;
  box-shadow: 0 25px 60px rgba(15, 23, 42, 0.25);
  width: 100%;
  max-width: 620px;
  padding: 28px;
  position: relative;
  animation: slideUp 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes slideUp {
  from { opacity: 0; transform: translateY(20px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.crawl-modal-header {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 20px;
}

.crawl-modal-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: linear-gradient(135deg, #DBEAFE 0%, #BFDBFE 100%);
  color: #2563EB;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  flex-shrink: 0;
}

.crawl-modal-header h3 {
  font-family: var(--font-display);
  font-size: 19px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0 0 4px 0;
  letter-spacing: 0.3px;
}

.crawl-modal-subtitle {
  font-size: 13px;
  color: var(--text-secondary);
  margin: 0;
  line-height: 1.5;
}

.crawl-modal-close {
  background: none;
  border: none;
  font-size: 28px;
  line-height: 1;
  color: var(--text-muted);
  cursor: pointer;
  padding: 0;
  margin: -4px -4px 0 0;
  transition: color 0.15s ease;
}

.crawl-modal-close:hover {
  color: var(--text-primary);
}

.crawl-progress-wrapper {
  margin-bottom: 18px;
}

.crawl-progress-bar-bg {
  height: 10px;
  background: #E2E8F0;
  border-radius: var(--r-pill);
  overflow: hidden;
  margin-bottom: 8px;
}

.crawl-progress-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #2563EB, #10B981, #F59E0B);
  border-radius: var(--r-pill);
  transition: width 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.crawl-progress-stats {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-secondary);
}

#crawl-progress-percent {
  font-family: var(--font-mono);
  font-weight: 800;
  color: #2563EB;
}

.crawl-log-terminal {
  background: #0F172A;
  border-radius: 12px;
  padding: 14px 16px;
  color: #E2E8F0;
  font-family: var(--font-mono);
  font-size: 12px;
  margin-bottom: 20px;
  border: 1px solid #1E293B;
}

.crawl-terminal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 11px;
  color: #94A3B8;
  padding-bottom: 8px;
  margin-bottom: 10px;
  border-bottom: 1px solid #334155;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.crawl-pulse-active {
  color: #34D399;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 700;
}

.crawl-terminal-logs {
  max-height: 140px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  scrollbar-width: thin;
}

.term-line {
  line-height: 1.5;
  word-break: break-word;
}

.term-line.info {
  color: #93C5FD;
}

.term-line.active {
  color: #FDE047;
}

.term-line.success {
  color: #6EE7B7;
  font-weight: 700;
}

.term-time {
  color: #64748B;
  margin-right: 6px;
}

.crawl-modal-summary {
  margin-bottom: 20px;
  animation: fadeIn 0.3s ease;
}

.summary-metric-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

@media (max-width: 600px) {
  .summary-metric-row {
    grid-template-columns: 1fr;
    gap: 8px;
  }
}

.summary-metric-card {
  background: #F8FAFC;
  border: 1px solid #E2E8F0;
  border-radius: 12px;
  padding: 12px 14px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.summary-metric-card.highlight {
  background: #EFF6FF;
  border-color: #BFDBFE;
}

.sm-label {
  font-size: 11px;
  color: var(--text-muted);
  text-transform: uppercase;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.sm-value {
  font-family: var(--font-mono);
  font-size: 17px;
  font-weight: 800;
  color: #1E293B;
}

.summary-metric-card.highlight .sm-value {
  color: #1D4ED8;
}

.sm-sub {
  font-size: 11.5px;
  color: var(--emerald-600);
  font-weight: 600;
}

