// Hợp nhất dữ liệu mới vào lịch sử Vietlott với kiểm định chặt chẽ chống lẫn lộn
mergeVietlottData(gameType, newDraws) {
  if (!newDraws || !Array.isArray(newDraws)) return 0;
  let addedCount = 0;
  let existing = this.data.vietlott[gameType] || [];

  // 1. Lọc sạch dữ liệu rác/lẫn lộn trong existing
  if (gameType === 'mega-6-45') {
    existing = existing.filter(d => {
      const nums = d.winningNumbers || [];
      const hasOver45 = nums.some(n => n > 45);
      const isPowerId = d.drawId && d.drawId.startsWith('#014');
      return !hasOver45 && !isPowerId && d.date !== '2026-10-15';
    });
  } else if (gameType === 'power-6-55') {
    existing = existing.filter(d => {
      const isMegaId = d.drawId && d.drawId.startsWith('#015');
      return !isMegaId;
    });
  }

  // 2. Nạp dữ liệu mới
  newDraws.forEach(draw => {
    // Xác thực nghiêm ngặt loại vé
    if (gameType === 'mega-6-45') {
      const nums = draw.winningNumbers || [];
      if (nums.some(n => n > 45) || (draw.drawId && draw.drawId.startsWith('#014')) || draw.date === '2026-10-15') {
        return;
      }
    }
    const foundIdx = existing.findIndex(d => d.date === draw.date || d.drawId === draw.drawId);
    if (foundIdx === -1) {
      existing.unshift(draw);
      addedCount++;
    } else {
      existing[foundIdx] = { ...existing[foundIdx], ...draw };
    }
  });

  this.data.vietlott[gameType] = existing.sort((a, b) => new Date(b.date) - new Date(a.date));
  return addedCount;
}

