args.ReplacementContent:
:root {
  color-scheme: light;

  /* 1. HỆ THỐNG MÀU QUANT EDITORIAL (RESEARCH PUBLICATION GRADE) */
  --bg-canvas: #F6F5F0;        /* Nền giấy ngà ấm nhẹ, chuyên nghiệp, không chói */
  --bg-card: #FFFFFF;          /* Nền card trắng tinh tế, sắc nét */
  --bg-card-elevated: #FFFFFF;
  --bg-surface: #FFFFFF;
  --bg-surface-muted: #EFECE6; /* Nền bảng phụ, strip header */
  --bg-subtle: #F0EDE6;        /* Khối con, chip nhẹ */
  --bg-hover: #F8F7F3;

  /* Nền kính mờ sáng tối giản */
  --card-glass: rgba(255, 255, 255, 0.94);
  --card-glass-elevated: rgba(255, 255, 255, 0.98);

  /* Màu chữ Sắc Nét, Tương Phản Chuẩn WCAG AAA */
  --text-primary: #1C1F1B;     /* Đen than chì trầm - Độ đọc tuyệt đối */
  --text-secondary: #5C625A;   /* Xám rêu ấm - Nhãn & mô tả */
  --text-muted: #7E847C;       /* Metadata, timestamp */
  --text-gold: #9A6B24;        /* Vàng đồng trầm học thuật */

  /* Điểm nhấn thương hiệu chủ đạo (Single Primary Accent) */
  --accent: #9A6B24;           /* Vàng đồng trầm quý phái */
  --accent-soft: #F4EEDF;      /* Nền nhấn dịu mắt */
  --accent-hover: #82581A;
  --accent-border: #D8C7A5;

  /* Màu ngữ nghĩa trạng thái (Semantic Only - Không dùng làm màu trang trí) */
  --success: #1E6B52;          /* Xanh ngọc lục bảo thẫm */
  --success-soft: #E8F4F0;
  --warning: #945312;          /* Nâu hổ phách */
  --warning-soft: #FBF0E4;
  --danger: #9E3834;           /* Đỏ ruby thẫm */
  --danger-soft: #FCEEEC;
  --info: #2B5770;             /* Xanh lam trầm */
  --info-soft: #EBF2F6;

  /* Đường phân cách sợi tóc thanh lịch (Minimal 1px Borders) */
  --line-subtle: #E2DFD8;
  --line-medium: #CDC9C0;
  --line-strong: #9E998E;
  --line-gold: rgba(154, 107, 36, 0.35);
  --line-gold-bright: #9A6B24;

  /* Backward Compatibility Aliases */
  --gold-50: #FFFDF8;
  --gold-100: #F4EEDF;
  --gold-300: #D8C7A5;
  --gold-400: #9A6B24;
  --gold-500: #82581A;
  --gold-600: #6B4712;

  --blue-50: #EBF2F6;
  --blue-100: #D7E5ED;
  --blue-500: #2B5770;
  --blue-600: #1F3F52;

  --emerald-50: #E8F4F0;
  --emerald-100: #D1E9E1;
  --emerald-400: #288467;
  --emerald-500: #1E6B52;
  --emerald-600: #16533F;

  --rose-50: #FCEEEC;
  --rose-100: #F7D7D5;
  --rose-500: #9E3834;
  --rose-600: #822C28;

  --purple-50: #F3EEF8;
  --purple-500: #684882;

  /* 2. TYPOGRAPHY SYSTEM */
  --font-sans: 'Be Vietnam Pro', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-display: 'Playfair Display', Georgia, serif;
  --font-mono: 'JetBrains Mono', ui-monospace, 'Consolas', monospace;

  /* 3. ĐỔ BÓNG MỊN MÀNG TIẾT CHẾ (EDITORIAL SUBTLE SHADOWS) */
  --sh-card: 0 1px 3px rgba(28, 31, 27, 0.05), 0 1px 2px rgba(28, 31, 27, 0.03);
  --sh-elevated: 0 6px 16px -2px rgba(28, 31, 27, 0.07), 0 2px 6px -1px rgba(28, 31, 27, 0.03);
  --sh-gold-glow: 0 0 0 1px rgba(154, 107, 36, 0.25), 0 4px 12px -2px rgba(154, 107, 36, 0.12);
  --sh-gold-badge: 0 1px 3px rgba(154, 107, 36, 0.12);
  --sh-emerald-glow: 0 0 0 1px rgba(30, 107, 82, 0.25), 0 4px 12px -2px rgba(30, 107, 82, 0.12);

  /* 4. BO GÓC CHUẨN MỰC (DISCIPLINED RADII) */
  --r-xs: 4px;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 14px;
  --r-xl: 18px;
  --r-pill: 9999px;

  /* Backward Compatibility Aliases for Components */
  --ink-950: #FFFFFF;
  --ink-900: #FFFFFF;
  --ink-850: #F6F5F0;
  --ink-800: #EFECE6;
  --ink-750: #E2DFD8;
  --ink-card-glass: rgba(255, 255, 255, 0.96);
