:root {
  color-scheme: light;

  /* 1. BẢNG MÀU TƯƠI SÁNG & SANG TRỌNG (FRESH LIGHT PALETTE) */
  --bg-canvas: #F8FAFC;        /* Nền ứng dụng sáng sạch */
  --bg-card: #FFFFFF;          /* Nền card trắng tinh khôi */
  --bg-card-elevated: #FFFFFF;
  --bg-subtle: #F1F5F9;        /* Nền khối con */
  --bg-hover: #F8FAFC;

  /* Nền kính mờ sáng nhẹ (Light Frosted Glass) */
  --card-glass: rgba(255, 255, 255, 0.92);
  --card-glass-elevated: rgba(255, 255, 255, 0.98);

  /* Màu chữ Sắc Nét, Tương Phản Chuẩn Cao Cấp (High-Legibility Typography) */
  --text-primary: #0F172A;     /* Đen than Slate 900 - Dễ đọc tối đa */
  --text-secondary: #475569;   /* Xám Slate 600 - Nhãn & phụ đề */
  --text-muted: #64748B;       /* Slate 500 - Timestamp & metadata */
  --text-gold: #B45309;        /* Vàng hổ phách quý tộc */

  /* 2. HỆ THỐNG MÀU NHẤN MAY MẮN & DATA VIZ */
  --gold-50: #FFFBEB;
  --gold-100: #FEF3C7;
  --gold-300: #FCD34D;
  --gold-400: #F59E0B;        /* Vàng Hoàng Kim tươi sáng */
  --gold-500: #D97706;
  --gold-600: #B45309;

  --blue-50: #EFF6FF;
  --blue-100: #DBEAFE;
  --blue-500: #2563EB;        /* Xanh Hoàng Gia Royal Blue */
  --blue-600: #1D4ED8;

  --emerald-50: #ECFDF5;
  --emerald-100: #D1FAE5;
  --emerald-400: #10B981;
  --emerald-500: #059669;     /* Xanh Ngọc Bích Trạng Thái */
  --emerald-600: #047857;

  --rose-50: #FEF2F2;
  --rose-100: #FEE2E2;
  --rose-500: #DC2626;        /* Đỏ May Mắn Vietlott / Đặc Biệt */
  --rose-600: #B91C1C;

  --purple-50: #FAF5FF;
  --purple-500: #7C3AED;      /* Tím Jackpot */

  /* Đường viền sợi tóc sắc nét (Clean Borders) */
  --line-subtle: #E2E8F0;
  --line-medium: #CBD5E1;
  --line-strong: #94A3B8;
  --line-gold: rgba(245, 158, 11, 0.38);
  --line-gold-bright: #F59E0B;

  /* 3. TYPOGRAPHY SYSTEM */
  --font-sans: 'Be Vietnam Pro', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-display: 'Playfair Display', Georgia, serif;
  --font-mono: 'JetBrains Mono', ui-monospace, 'Consolas', monospace;

  /* 4. ĐỔ BÓNG MỀM MẠI THANH KHIẾT (DIFFUSED LIGHT SHADOWS) */
  --sh-card: 0 4px 20px -2px rgba(15, 23, 42, 0.05), 0 2px 6px -1px rgba(15, 23, 42, 0.02);
  --sh-elevated: 0 12px 30px -4px rgba(15, 23, 42, 0.08), 0 4px 12px -2px rgba(15, 23, 42, 0.03);
  --sh-gold-glow: 0 0 0 1px rgba(245, 158, 11, 0.28), 0 8px 24px -4px rgba(245, 158, 11, 0.16);
  --sh-gold-badge: 0 2px 6px rgba(217, 119, 6, 0.15);
  --sh-emerald-glow: 0 0 0 1px rgba(16, 185, 129, 0.28), 0 8px 24px -4px rgba(16, 185, 129, 0.16);

  /* 5. BO GÓC MỀM MẠI */
  --r-xs: 6px;
  --r-sm: 10px;
  --r-md: 16px;
  --r-lg: 20px;
  --r-xl: 26px;
  --r-pill: 9999px;

  /* Backward Compatibility Aliases for Components (All Light-Optimized) */
  --ink-950: #FFFFFF;
  --ink-900: #FFFFFF;
  --ink-850: #F8FAFC;
  --ink-800: #F1F5F9;
  --ink-750: #E2E8F0;
  --ink-card-glass: rgba(255, 255, 255, 0.96);
  --on-ink: #0F172A;
  --on-ink-subtle: #475569;
  --on-ink-muted: #64748B;
  --blue-400: #2563EB;
  --indigo-400: #4F46E5;

  /* Chuyển động tương tác chuẩn */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
  --dur-fast: 160ms;
  --dur-normal: 280ms;
}

