/* ===================================================================
   HEADER ỨNG DỤNG (QUANT EDITORIAL HEADER)
   =================================================================== */
.header-wrapper {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 24px;
  background: var(--bg-surface);
  border: 1px solid var(--line-subtle);
  border-radius: var(--r-md);
  margin-bottom: 20px;
  box-shadow: var(--sh-card);
  position: relative;
}

.header-wrapper::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent);
}

.brand-section {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-icon-box {
  width: 44px;
  height: 44px;
  border-radius: var(--r-sm);
  background: var(--accent-soft);
  border: 1px solid var(--accent-border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  color: var(--accent);
  transition: background-color var(--dur-fast), border-color var(--dur-fast);
}

.brand-icon-box:hover {
  background: var(--bg-card);
  border-color: var(--accent);
}

.brand-titles h1 {
  font-family: var(--font-sans);
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.3px;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 2px;
}

.brand-badge {
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.5px;
  padding: 2px 8px;
  border-radius: var(--r-xs);
  background: var(--bg-subtle);
  color: var(--text-secondary);
  border: 1px solid var(--line-subtle);
  text-transform: uppercase;
}

.brand-subtitle {
  font-size: 13px;
  color: var(--text-secondary);
  font-weight: 400;
  letter-spacing: 0.1px;
}

.status-section {
  display: flex;
  align-items: center;
  gap: 12px;
}

.live-status-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 12px;
  background: var(--bg-surface);
  border: 1px solid var(--line-subtle);
  border-radius: var(--r-sm);
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
}

.pulse-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background-color: var(--success);
  display: inline-block;
}

.btn-sync {
  background: var(--bg-surface);
  color: var(--text-primary);
  border: 1px solid var(--line-medium);
  padding: 7px 15px;
  border-radius: var(--r-sm);
  font-family: var(--font-sans);
  font-size: 12.5px;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  transition: all var(--dur-fast) var(--ease-out);
  box-shadow: 0 1px 2px rgba(28, 31, 27, 0.04);
}

.btn-sync:hover {
  background: var(--accent-soft);
  border-color: var(--accent);
  color: var(--accent);
}

.btn-sync:active {
  transform: translateY(1px);
}

/* ===================================================================
   TOP EXECUTIVE KPI STATS BAR (QUANT EDITORIAL METRICS)
   =================================================================== */
.kpi-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin-bottom: 22px;
}

@media (max-width: 1024px) {
  .kpi-summary-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }
}

@media (max-width: 640px) {
  .kpi-summary-grid {
    grid-template-columns: 1fr;
    gap: 10px;
    margin-bottom: 16px;
  }
}

.kpi-stat-card {
  background: var(--bg-surface);
  border: 1px solid var(--line-subtle);
  border-radius: var(--r-md);
  padding: 16px 18px;
  box-shadow: var(--sh-card);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  position: relative;
  transition: border-color var(--dur-fast), box-shadow var(--dur-fast);
}

.kpi-stat-card:hover {
  border-color: var(--line-medium);
  box-shadow: var(--sh-elevated);
}

/* Thẻ nổi bật chính (Consensus / Điểm tựa hội tụ) */
.kpi-stat-card.kpi-gold {
  border-color: var(--accent-border);
  background: linear-gradient(180deg, #FFFDF9 0%, #FFFFFF 100%);
