args.ReplacementContent:
.mode-tab.active {
  background: var(--bg-surface);
  color: var(--accent);
  border: 1px solid var(--accent-border);
  box-shadow: 0 1px 4px rgba(28, 31, 27, 0.06);
}

#mode-btn-xsmn.active {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--bg-surface);
}

#mode-btn-vietlott.active {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--bg-surface);
}

.direct-filter-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--line-subtle);
}

.today-stations-quick-group {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}

.today-pulse-label {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 12.5px;
  font-weight: 700;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.station-today-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background-color: var(--success);
  display: inline-block;
}

.today-fast-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}

.today-fast-pill-btn {
  background: var(--bg-surface);
  border: 1px solid var(--line-subtle);
  color: var(--text-secondary);
  padding: 5px 12px;
  border-radius: var(--r-sm);
  font-size: 12.5px;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  transition: all var(--dur-fast) var(--ease-out);
  box-shadow: 0 1px 2px rgba(28, 31, 27, 0.03);
}

.today-fast-pill-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
  border-color: var(--line-medium);
}

.today-fast-pill-btn.active {
  background: var(--accent-soft);
  color: var(--accent);
  border-color: var(--accent);
  font-weight: 700;
  box-shadow: 0 1px 3px rgba(154, 107, 36, 0.15);
}

.today-fast-pill-btn.active::before {
  content: '';
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background-color: var(--accent);
  display: inline-block;
}

.all-stations-dropdown-group {
  display: flex;
  align-items: center;
  gap: 8px;
}

.dropdown-label {
  font-size: 12.5px;
  color: var(--text-secondary);
  font-weight: 600;
  white-space: nowrap;
}

.direct-select {
  background: var(--bg-surface);
  color: var(--text-primary);
  border: 1px solid var(--line-medium);
  padding: 6px 12px;
  border-radius: var(--r-sm);
  font-family: var(--font-sans);
  font-size: 12.5px;
  font-weight: 600;
  outline: none;
  cursor: pointer;
  transition: border-color var(--dur-fast);
  min-width: 170px;
}

.direct-select:focus {
  border-color: var(--accent);
}

/* Nút chọn nhanh Vietlott to rõ ràng */
.vietlott-quick-buttons {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  width: 100%;
}

.vietlott-game-btn {
  background: var(--bg-surface);
  border: 1px solid var(--line-subtle);
  border-radius: var(--r-md);
  padding: 12px 16px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  transition: all var(--dur-fast) var(--ease-out);
  box-shadow: var(--sh-card);
}

.vietlott-game-btn:hover {
  border-color: var(--line-medium);
  background: var(--bg-hover);
}

.vietlott-game-btn.active {
  background: var(--accent-soft);
  border-color: var(--accent);
  box-shadow: 0 2px 8px rgba(154, 107, 36, 0.12);
}

.v-btn-badge {
  font-size: 13.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: var(--text-primary);
}

.v-btn-jackpot {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--accent);
  font-family: var(--font-mono);
}

.custom-select {
  background: var(--bg-surface);
  color: var(--text-primary);
  border: 1px solid var(--line-subtle);
  padding: 7px 12px;
  border-radius: var(--r-sm);
  font-family: var(--font-sans);
  font-size: 12.5px;
  font-weight: 500;
  outline: none;
  cursor: pointer;
  transition: border-color var(--dur-fast);
}

.custom-select:focus {
  border-color: var(--accent);
}

/* ===================================================================
   TÍNH NĂNG SINGLE-PAGE LIỀN MẠCH: 
   =================================================================== */
.main-nav-tabs {
  display: none !important;
}

/* Tất cả panel hiển thị tuần tự như các section trên 1 trang duy nhất */
.tab-view-panel {
  display: block !important;
  animation: none !important;
  margin-bottom: 36px;
}

/* ===================================================================
   TIÊU ĐỀ PHÂN ĐOẠN TRANG CUỘN LIỀN MẠCH (QUANT EDITORIAL SECTION HEADERS)
   =================================================================== */
.page-section-header {
  margin: 32px 0 16px 0;
  padding: 0 4px;
  border-left: 3px solid var(--accent);
  padding-left: 12px;
}

.page-section-header.header-gold,
.page-section-header.header-emerald,
.page-section-header.header-purple {
  border-left-color: var(--accent);
}

.section-title-line {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 4px;
}

.section-num-pill {
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: var(--r-xs);
  background: var(--bg-subtle);
  color: var(--text-secondary);
  border: 1px solid var(--line-subtle);
  letter-spacing: 0.5px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.section-heading {
  font-family: var(--font-sans);
  font-size: 20px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0;
  letter-spacing: -0.2px;
}

.section-subheading {
  font-size: 13px;
  color: var(--text-secondary);
  margin: 0;
  line-height: 1.5;
}

