/* ===================================================================
   LOTTO-QUANT LAB: COMPONENTS CSS
   Bóng số, Bảng kết quả, Thẻ thuật toán, Dashboard Phân Tích & Backtest
   Phong cách Quant Editorial: Tối giản, Học thuật, Rõ nét, Tương phản cao
   =================================================================== */

/* --- 1. THẺ NỀN TẢNG (QUANT EDITORIAL CARD) --- */
.quant-card {
  background: var(--bg-surface);
  border: 1px solid var(--line-subtle);
  border-radius: var(--r-md);
  padding: 20px 24px;
  box-shadow: var(--sh-card);
  margin-bottom: 22px;
  transition: border-color var(--dur-fast), box-shadow var(--dur-fast);
}

.quant-card:hover {
  border-color: var(--line-medium);
  box-shadow: var(--sh-elevated);
}

.card-header-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  padding-bottom: 14px;
  margin-bottom: 18px;
  border-bottom: 1px solid var(--line-subtle);
}

.card-title-group {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.card-title-group h2, 
.card-title-group h3 {
  font-family: var(--font-sans);
  font-size: 18px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
  letter-spacing: -0.2px;
}

.meta-info-badge {
  font-family: var(--font-sans);
  font-size: 11px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: var(--r-xs);
  background: var(--bg-subtle);
  color: var(--text-secondary);
  border: 1px solid var(--line-subtle);
  letter-spacing: 0.2px;
}

/* --- 2. BÓNG SỐ VIETLOTT & CHIPS LÔ TÔ XSMN (PRECISION FLAT BALLS) --- */
.ball-group {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
}

/* Quả cầu số Vietlott dạng Flat Precision thanh lịch */
.lotto-ball {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 16px;
  color: var(--text-primary);
  background: var(--bg-surface);
  border: 1.5px solid var(--line-medium);
  box-shadow: 0 1px 3px rgba(28, 31, 27, 0.05);
  user-select: none;
  transition: border-color var(--dur-fast), transform var(--dur-fast);
}

.lotto-ball:hover {
  border-color: var(--accent);
  transform: translateY(-1px);
}

.lotto-ball.gold {
  background: var(--accent-soft);
  border-color: var(--accent-border);
  color: var(--accent);
}

.lotto-ball.bonus {
  background: var(--danger-soft);
  border-color: var(--danger);
  color: var(--danger);
}

/* Thẻ số Lô Tô 2 số XSMN */
.lotto-chip {
  padding: 5px 12px;
  border-radius: var(--r-sm);
  background: var(--bg-surface);
  border: 1px solid var(--line-subtle);
  font-family: var(--font-mono);
  font-weight: 600;
  font-size: 14px;
  color: var(--text-primary);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  box-shadow: 0 1px 2px rgba(28, 31, 27, 0.03);
  transition: all var(--dur-fast) var(--ease-out);
}

.lotto-chip:hover {
  border-color: var(--accent);
  background: var(--bg-hover);
}

.lotto-chip.hit {
  background: var(--success-soft);
  border-color: var(--success);
  color: var(--success);
  font-weight: 700;
}

.lotto-chip.special-hit {
  background: var(--accent-soft);
  border-color: var(--accent);
  color: var(--accent);
  font-weight: 700;
}

/* --- 3. BẢNG 18 GIẢI XSMN (EDITORIAL STATEMENT STYLE) --- */
.results-card-container {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 20px;
  margin-bottom: 22px;
}

@media (max-width: 950px) {
  .results-card-container {
    grid-template-columns: minmax(0, 1fr);
    width: 100%;
    box-sizing: border-box;
  }
}

.xsmn-table {
  width: 100%;
  border-collapse: collapse;
}

.xsmn-table tr {
  border-bottom: 1px solid var(--line-subtle);
}

.xsmn-table tr:nth-child(even) {
  background: #FAF9F6;
}

.xsmn-table tr:hover {
  background: var(--bg-hover);
}

.xsmn-table td {
  padding: 9px 12px;
  font-size: 13.5px;
}

.xsmn-table .prize-label {
  font-family: var(--font-sans);
  font-weight: 600;
  color: var(--text-secondary);
  width: 110px;
  text-transform: uppercase;
  font-size: 11.5px;
  letter-spacing: 0.3px;
}

.xsmn-table .prize-numbers {
  font-family: var(--font-mono);
