.rec-card {
  background: var(--bg-surface);
  border: 1px solid var(--line-subtle);
  border-radius: var(--r-md);
  padding: 18px 20px;
  box-shadow: var(--sh-card);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.rec-card.rec-gold {
  border-color: var(--accent-border);
}

.rec-card.rec-emerald {
  border-color: rgba(30, 107, 82, 0.3);
}

.rec-card.rec-rose {
  border-color: rgba(158, 56, 52, 0.3);
}

.rec-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.rec-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.rec-gold .rec-title { color: var(--accent); }
.rec-emerald .rec-title { color: var(--success); }
.rec-rose .rec-title { color: var(--danger); }

.rec-ball-box {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 10px;
}

.rec-ball {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 38px;
  height: 38px;
  padding: 0 8px;
  border-radius: var(--r-sm);
  font-family: var(--font-mono);
  font-size: 16px;
  font-weight: 800;
  color: var(--text-primary);
  background: var(--bg-surface);
  border: 1.5px solid var(--line-medium);
  box-shadow: 0 1px 2px rgba(28, 31, 27, 0.04);
}

.rec-gold .rec-ball {
  background: var(--accent-soft);
  border-color: var(--accent-border);
  color: var(--accent);
}

.rec-emerald .rec-ball {
  background: var(--success-soft);
  border-color: rgba(30, 107, 82, 0.3);
  color: var(--success);
}

.rec-rose .rec-ball {
  background: var(--danger-soft);
  border-color: rgba(158, 56, 52, 0.3);
  color: var(--danger);
}

.rec-desc {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* Lưới hiển thị các biểu đồ đa chiều */
.dashboard-charts-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  margin-bottom: 22px;
}

@media (max-width: 992px) {
  .dashboard-charts-grid {
    grid-template-columns: 1fr;
  }
}

.chart-card {
  background: var(--bg-surface);
  border: 1px solid var(--line-subtle);
  border-radius: var(--r-md);
  padding: 18px 20px;
  box-shadow: var(--sh-card);
  display: flex;
  flex-direction: column;
}

.chart-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--line-subtle);
}

.chart-card-title-group h3 {
  font-family: var(--font-sans);
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0 0 2px 0;
}

.chart-card-subtitle {
  font-size: 11.5px;
  color: var(--text-muted);
}

.chart-canvas-box {
  position: relative;
  width: 100%;
  height: 250px;
  flex: 1;
}

.donuts-container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  height: 250px;
}

@media (max-width: 480px) {
  .donuts-container {
    grid-template-columns: 1fr;
    height: auto;
  }
}

.single-donut-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  position: relative;
  height: 100%;
}

.donut-label-center {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
  pointer-events: none;
}

.donut-pct {
  font-family: var(--font-mono);
  font-size: 17px;
  font-weight: 800;
  color: var(--text-primary);
}

.donut-sub {
  font-size: 10px;
  color: var(--text-muted);
  text-transform: uppercase;
}

.chart-footer-insight {
  margin-top: 12px;
  padding: 8px 12px;
  background: var(--bg-subtle);
  border: 1px solid var(--line-subtle);
  border-radius: var(--r-sm);
  font-size: 11.5px;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 6px;
}

/* --- 7. BẢNG XẾP HẠNG & BACKTEST (LEADERBOARD) --- */
.leaderboard-table, 
.backtest-results-table {
  width: 100%;
  border-collapse: collapse;
}

.leaderboard-table th, 
.backtest-results-table th {
  background: var(--bg-surface-muted);
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  padding: 10px 12px;
  text-align: left;
  border-bottom: 1px solid var(--line-medium);
}

.leaderboard-table td, 
.backtest-results-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--line-subtle);
  font-size: 13.5px;
  color: var(--text-primary);
}

.leaderboard-table tr:hover, 
.backtest-results-table tr:hover {
  background: var(--bg-hover);
}

.rank-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  font-family: var(--font-mono);
  font-weight: 800;
  font-size: 11px;
}

.rank-1 { background: var(--accent-soft); color: var(--accent); border: 1px solid var(--accent-border); }
.rank-2 { background: var(--bg-subtle); color: var(--text-secondary); border: 1px solid var(--line-medium); }
.rank-3 { background: var(--bg-subtle); color: var(--text-muted); border: 1px solid var(--line-subtle); }
.rank-other { background: transparent; color: var(--text-muted); }

