import { LOTTO_CONFIG } from '../config.js';

/**
 * THUẬT TOÁN 5: Chuỗi Thời Gian & Trung Bình Trượt (EMA & Day-of-Week Seasonality)
 * Công thức: EMA_t = α * X_t + (1 - α) * EMA_{t-1} (với hệ số làm mượt α = 0.25)
 * Kết hợp chỉ số tương quan theo thứ trong tuần dựa trên lịch quay chính thức.
 */

export const MovingAverageAlgorithm = {
  id: "moving-average",
  name: "EMA & Chu kỳ Thứ",

  /**
   * Bóc tách thứ trong tuần (0: CN, 1: T2, ... 6: T7) an toàn tuyệt đối khỏi lệch timezone
   */
  parseDayOfWeek(dateStr) {
    if (!dateStr || typeof dateStr !== 'string') return 1;
    const parts = dateStr.split('-');
    if (parts.length === 3) {
      const y = parseInt(parts[0], 10);
      const m = parseInt(parts[1], 10) - 1;
      const d = parseInt(parts[2], 10);
      // Dùng 12:00 trưa để triệt tiêu mọi biến động giờ mùa hè hoặc UTC offset
      return new Date(y, m, d, 12, 0, 0).getDay();
    }
    return 1;
  },

  predict(historyData, options = {}) {
    const isVietlott = options.isVietlott || false;
    const maxNum = isVietlott ? (options.totalBalls || 45) : 99;
    const minNum = isVietlott ? 1 : 0;
    const topN = options.topN || (isVietlott ? 6 : 5);
    const nDraws = Math.min(historyData.length, 40);
    const alpha = 0.25; // Hệ số làm mượt EMA
    const stationOrGame = options.stationOrGame || (isVietlott ? 'mega-6-45' : 'tphcm');

    if (nDraws < 3) {
      return this.getDefaultPrediction(isVietlott, maxNum, topN);
    }

    // 1. Xác định thứ trong tuần của kỳ quay MỤC TIÊU chuẩn xác theo lịch quay
    let targetDayOfWeek = 1;
    let targetDateStr = options.targetDrawDate || null;

    if (targetDateStr) {
      targetDayOfWeek = this.parseDayOfWeek(targetDateStr);
    } else if (historyData[0] && historyData[0].date) {
      // Tra cứu ngày mở thưởng hợp lệ tiếp theo của đài/game qua lịch chính thức trong LOTTO_CONFIG
      const nextDraw = LOTTO_CONFIG.getNextDrawDate(historyData[0].date, stationOrGame, isVietlott);
      targetDayOfWeek = nextDraw.dayOfWeek;
      targetDateStr = nextDraw.date;
    }

    // 2. Khởi tạo bảng chỉ số
    const numStats = {};
    for (let i = minNum; i <= maxNum; i++) {
      const key = isVietlott ? i : (i < 10 ? '0' + i : '' + i);
      numStats[key] = {
        num: key,
        ema: 0.1,
        dayOfWeekHits: 0,
        dayOfWeekTotal: 0
      };
    }

    // 3. Duyệt chuỗi thời gian từ cũ đến mới (t = nDraws-1 lùi về 0)
    for (let t = nDraws - 1; t >= 0; t--) {
      const draw = historyData[t];
      const nums = isVietlott ? (draw.winningNumbers || []) : (draw.lottoPairs || []);
      const numSet = new Set(nums.map(n => isVietlott ? Number(n) : String(n)));

      const drawDay = this.parseDayOfWeek(draw.date);

      for (let i = minNum; i <= maxNum; i++) {
        const key = isVietlott ? i : (i < 10 ? '0' + i : '' + i);
        const appeared = numSet.has(key) ? 1.0 : 0.0;

        // Cập nhật EMA
        numStats[key].ema = alpha * appeared + (1 - alpha) * numStats[key].ema;

        // Cập nhật thống kê theo thứ
        if (drawDay === targetDayOfWeek) {
          numStats[key].dayOfWeekTotal++;
          if (appeared) numStats[key].dayOfWeekHits++;
        }
      }
    }

    // 4. Tính điểm tổng hợp (Momentum + Seasonality với Bayesian shrinkage)
    const stats = [];
    const scores = {};
    const basePrior = isVietlott ? (topN / maxNum) : 0.18; // Tỷ lệ xuất hiện kỳ vọng lý thuyết

    for (let i = minNum; i <= maxNum; i++) {
      const key = isVietlott ? i : (i < 10 ? '0' + i : '' + i);
      const item = numStats[key];

      const emaScore = item.ema * 100; // Thang 0 - 100

      // Áp dụng shrinkage làm mượt mẫu nhỏ: nếu kỳ quay đúng thứ < 3, co về prior kỳ vọng
      let dayRatio = basePrior;
      if (item.dayOfWeekTotal >= 3) {
        // Laplace / M-estimate smoothing: (hits + 1*prior) / (total + 1)
        dayRatio = (item.dayOfWeekHits + 1 * basePrior) / (item.dayOfWeekTotal + 1);
      } else if (item.dayOfWeekTotal > 0) {
        dayRatio = (item.dayOfWeekHits + 2 * basePrior) / (item.dayOfWeekTotal + 2);
      }
      const dayScore = Math.min(dayRatio * 100, 100);

      // Điểm cuối: 70% xung lượng EMA + 30% hiệu ứng mùa vụ theo thứ (đã làm mượt)
      const finalScore = Math.round((emaScore * 0.70 + dayScore * 0.30) * 10) / 10;
      scores[key] = finalScore;

      stats.push({
        num: key,
        ema: Math.round(item.ema * 1000) / 1000,
        dayHits: item.dayOfWeekHits,
        dayTotal: item.dayOfWeekTotal,
        score: finalScore
      });
    }

    stats.sort((a, b) => b.score - a.score || b.ema - a.ema);
    const topCandidates = stats.slice(0, topN).map(s => s.num);

    const dayNames = ['Chủ Nhật', 'Thứ Hai', 'Thứ Ba', 'Thứ Tư', 'Thứ Năm', 'Thứ Sáu', 'Thứ Bảy'];
    const targetDayName = dayNames[targetDayOfWeek] || `Thứ ${targetDayOfWeek + 1}`;

    return {
      id: this.id,
      name: this.name,
      predictions: topCandidates,
      scores,
      metrics: {
        alphaSmoothing: alpha,
        targetDayOfWeek,
        targetDayName,
        targetDate: targetDateStr,
        topMomentum: stats.slice(0, 10)
      },
      explanation: `Đường trung bình trượt EMA nhận diện đà tăng xác suất (Momentum), kết hợp nhịp mở thưởng ${targetDayName}. Các số đang có độ dốc EMA hướng lên mạnh nhất là ${topCandidates.join(', ')}.`
    };
  },

