/**
 * Bộ sinh số ngẫu nhiên giả lập có Seed (Mulberry32 PRNG)
 * Đảm bảo 100% khả năng tái lập trong kiểm định học thuật và thực nghiệm
 */
export function createPrng(seed = 123456789) {
  let s = (seed >>> 0) || 1;
  return function() {
    s = (s + 0x6D2B79F5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t >>> 0) / 4294967296);
  };
}

/**
 * Tạo seed xác định dựa trên chuỗi lịch sử (Date & ID) khi người dùng không truyền seed
 */
function deriveSeedFromHistory(historyData, isVietlott) {
  if (!historyData || !historyData.length) return isVietlott ? 450001 : 990001;
  const first = historyData[0];
  const str = `${first.date || ''}_${first.drawId || ''}_${isVietlott ? 'V' : 'M'}`;
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash + str.charCodeAt(i)) | 0;
  }
  return Math.abs(hash) || 123456789;
}

/**
 * THUẬT TOÁN 3: Mô Phỏng Số Học Monte Carlo (Monte Carlo 10,000 Iterations)
 * Chạy 10.000 kịch bản quay thưởng giả lập theo phân phối tích lũy xác suất (CDF)
 * từ lịch sử để tìm vùng hội tụ có tần suất xuất hiện cực đại.
 */
export const MonteCarloAlgorithm = {
  id: "monte-carlo",
  name: "Mô phỏng Monte Carlo (10k)",

  predict(historyData, options = {}) {
    const isVietlott = options.isVietlott || false;
    const maxNum = isVietlott ? (options.totalBalls || 45) : 99;
    const minNum = isVietlott ? 1 : 0;
    const topN = options.topN || (isVietlott ? 6 : 5);
    const numDrawBalls = isVietlott ? (options.pickBalls || 6) : 18; // Vietlott rút 6 quả, XSMN có 18 con lô
    const nDraws = Math.min(historyData.length, 35);
    const SIMULATIONS = options.simulations || 10000;

    if (nDraws === 0) {
      return this.getDefaultPrediction(isVietlott, maxNum, topN);
    }

    // 1. Khởi tạo Seeded PRNG để đảm bảo kết quả tái lập tuyệt đối khi cùng Input & Seed
    const seed = options.seed !== undefined 
      ? options.seed 
      : (options.rng ? null : deriveSeedFromHistory(historyData, isVietlott));
    const random = options.rng || createPrng(seed);

    // 2. Tính trọng số xác suất cho từng số dựa trên tần suất và độ mới
    const weights = {};
    for (let i = minNum; i <= maxNum; i++) {
      const key = isVietlott ? i : (i < 10 ? '0' + i : '' + i);
      weights[key] = 1.0; // Trọng số nền cơ bản
    }

    const recentDraws = historyData.slice(0, nDraws);
    recentDraws.forEach((draw, drawIdx) => {
      // Hệ số phân rã theo thời gian: kỳ càng gần thì trọng số ảnh hưởng càng cao
      const recencyFactor = 1.0 + (1.0 - drawIdx / nDraws);
      const nums = isVietlott ? (draw.winningNumbers || []) : (draw.lottoPairs || []);
      nums.forEach(n => {
        const key = isVietlott ? Number(n) : String(n);
        if (weights[key] !== undefined) {
          weights[key] += recencyFactor;
        }
      });
    });

    // 3. Xây dựng phân phối xác suất tích lũy (Cumulative Distribution Function - CDF)
    const keys = Object.keys(weights);
    const totalWeight = keys.reduce((acc, k) => acc + weights[k], 0);

    const cdf = [];
    let cumulative = 0;
    keys.forEach(k => {
      cumulative += weights[k] / totalWeight;
      cdf.push({ num: isVietlott ? Number(k) : k, cumProb: cumulative });
    });
    cdf[cdf.length - 1].cumProb = 1.0;

    // 4. Thực hiện các lượt mô phỏng quay thưởng theo luật game cụ thể
    const simulationHits = {};
    keys.forEach(k => {
      const key = isVietlott ? Number(k) : k;
      simulationHits[key] = 0;
    });

    // Lấy mẫu theo CDF bằng Seeded PRNG
    const sampleFromCDF = () => {
      const r = random();
      for (let i = 0; i < cdf.length; i++) {
        if (r <= cdf[i].cumProb) {
          return cdf[i].num;
        }
      }
      return cdf[cdf.length - 1].num;
    };

    // Mô phỏng 10.000 kịch bản:
    // - Vietlott (Mega/Power): Rút KHÔNG HOÀN LẠI (Strictly distinct balls in a single draw)
    // - XSMN (18 giải): Rút ĐỘC LẬP TỪNG GIẢI (Cho phép đuôi trùng lặp giữa các giải khác nhau)
    for (let sim = 0; sim < SIMULATIONS; sim++) {
      if (isVietlott) {
        // Vietlott: 6 quả bóng phân biệt
        const pickedThisSim = new Set();
        let attempts = 0;
        while (pickedThisSim.size < numDrawBalls && attempts < numDrawBalls * 5) {
          attempts++;
          pickedThisSim.add(sampleFromCDF());
        }
        pickedThisSim.forEach(b => {
          if (simulationHits[b] !== undefined) {
            simulationHits[b]++;
          }
        });
      } else {
        // XSMN: 18 giải thưởng độc lập (cho phép trùng nhau)
        for (let prizeIdx = 0; prizeIdx < numDrawBalls; prizeIdx++) {
          const ball = sampleFromCDF();
          if (simulationHits[ball] !== undefined) {
            simulationHits[ball]++;
          }
        }
      }
    }

    // 5. Tính điểm chuẩn hóa & độ biến động thống kê qua các kịch bản
    const stats = [];
    const scores = {};
    const hitValues = [];

    keys.forEach(k => {
      const key = isVietlott ? Number(k) : k;
      const hits = simulationHits[key];
      hitValues.push(hits);
      // Tỷ lệ xuất hiện trung bình mỗi kỳ mô phỏng (%)
      const frequencyInSim = (hits / SIMULATIONS) * 100;
      const score = Math.round(frequencyInSim * 10) / 10;
      scores[key] = score;

      stats.push({
        num: key,
        hits,
        score
      });
    });

    // Tính độ biến động thống kê (Standard deviation of simulation hits)
    const meanHits = hitValues.reduce((a, b) => a + b, 0) / (hitValues.length || 1);
    const variance = hitValues.reduce((acc, h) => acc + Math.pow(h - meanHits, 2), 0) / (hitValues.length || 1);
    const stdDevHits = Math.round(Math.sqrt(variance) * 10) / 10;

    stats.sort((a, b) => b.score - a.score || b.hits - a.hits);
    const topCandidates = stats.slice(0, topN).map(s => s.num);

    return {
      id: this.id,
      name: this.name,
      predictions: topCandidates,
      scores,
      metrics: {
        totalSimulations: SIMULATIONS,
        seedUsed: seed !== null ? seed : 'External-RNG',
        samplingMode: isVietlott ? 'Không hoàn lại (Vietlott Distinct)' : 'Độc lập 18 giải (XSMN Multi-Prize)',
        volatilityStdDev: stdDevHits,
        simulationVariance: `Độ lệch chuẩn hội tụ: ±${stdDevHits} lượt`,
        topHits: stats.slice(0, 10)
      },
      explanation: `Mô phỏng Monte Carlo ${SIMULATIONS.toLocaleString()} kịch bản (${isVietlott ? 'Vietlott rút không lặp' : 'XSMN 18 giải độc lập'}) qua phân phối tích lũy CDF. Các con số có tần suất xuất hiện cao nhất là ${topCandidates.join(', ')}.`
    };
  },

