  // Chuẩn hóa điểm số (Weighted Soft Voting)
  const stats = [];
  for (let i = minNum; i <= maxNum; i++) {
    const key = isVietlott ? i : (i < 10 ? '0' + i : '' + i);
    const normalizedScore = totalWeight > 0 ? (ensembleScores[key] / totalWeight) : 50;
    const finalScore = Math.round(normalizedScore * 10) / 10;
