  const topVotes = stats.slice(0, topN).reduce((acc, cur) => acc + cur.votes, 0);
  const maxPossibleVotes = topN * Math.max(subResults.length, 1);
  const consensusRatio = maxPossibleVotes > 0 ? (topVotes / maxPossibleVotes) : 0;
  // Tỷ lệ phần trăm đồng thuận thực tế (không cộng thêm offset ảo)
  const consensusPercent = Math.round(consensusRatio * 1000) / 10;

  // 4. Dự đoán Dãy 6 Số Giải Đặc Biệt (XSMN Positional Quant Model)
  const specialPrize = !isVietlott ? this.predictSpecialPrize(historyData, topCandidates) : null;

