  if (probA > 0 && probB > 0 && (seqCount > 0 || cooccurCount > 0)) {
    // Lift chuyển tiếp kỳ kế (Sequential Lift)
    const probSeq = seqCount / Math.max(nDraws - 1, 1);
    const seqLift = probSeq / (probA * probB);

    // Lift đồng xuất hiện cùng kỳ (In-Draw Co-occurrence Lift)
    const probCooccur = cooccurCount / nDraws;
    const cooccurLift = probCooccur / (probA * probB);

    // Lift tích hợp: 70% nhịp chuyển tiếp sang kỳ sau + 30% mức độ gắn kết cùng kỳ
    const combinedLift = (seqLift * 0.7) + (cooccurLift * 0.3);

    if (combinedLift > 0.9) {
      totalLift += combinedLift;
      matchedRules++;
      allPairRules.push({
        a: a,
        b: keyB,
        lift: Math.round(combinedLift * 100) / 100,
        seqCount,
        cooccurCount
      });
    }
  }
});

