// Hợp nhất dữ liệu mới vào lịch sử Vietlott với kiểm định chặt chẽ (100% trọn vẹn từ #00001)
mergeVietlottData(gameType, newDraws) {
  if (!newDraws || !Array.isArray(newDraws)) return 0;
  let addedCount = 0;
  let existing = this.data.vietlott[gameType] || [];

  newDraws.forEach(draw => {
    if (!draw || !draw.date) return;
    const nums = draw.winningNumbers || [];
    if (!Array.isArray(nums) || nums.length < 6) return;

    // Xác thực nghiêm ngặt loại vé theo giá trị bóng số hợp lệ
    if (gameType === 'mega-6-45') {
      if (nums.some(n => n > 45 || n < 1)) return;
    } else if (gameType === 'power-6-55') {
      if (nums.some(n => n > 55 || n < 1)) return;
    }

    const foundIdx = existing.findIndex(d => d.date === draw.date || (d.drawId && draw.drawId && d.drawId === draw.drawId));
    if (foundIdx === -1) {
      existing.push(draw);
      addedCount++;
    } else {
      existing[foundIdx] = { ...existing[foundIdx], ...draw };
    }
  });

