export const RandomBaselineAlgorithm = {
  id: "random-baseline",
  name: "Chuẩn Ngẫu Nhiên (Random Baseline)",

  predict(historyData, options = {}) {
    const isVietlott = options.isVietlott || false;
    const maxNum = isVietlott ? (options.totalBalls || 45) : 99;
    const minNum = isVietlott ? 1 : 0;
    const topN = options.topN || (isVietlott ? 6 : 5);

    // Seed giả lập xác định theo ngày mục tiêu để tái lập
    let seed = 123456789;
    if (options.targetDrawDate) {
      const s = String(options.targetDrawDate);
      for (let i = 0; i < s.length; i++) seed = ((seed << 5) - seed + s.charCodeAt(i)) | 0;
    }
    let s = (seed >>> 0) || 1;
    const rng = () => {
      s = (s + 0x6D2B79F5) | 0;
      let t = Math.imul(s ^ (s >>> 15), 1 | s);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t >>> 0) / 4294967296);
    };

    const preds = [];
    while (preds.length < topN) {
      const val = isVietlott
        ? Math.floor(rng() * (maxNum - minNum + 1)) + minNum
        : String(Math.floor(rng() * 100)).padStart(2, '0');
      if (!preds.includes(val)) {
        preds.push(val);
      }
    }

    return {
      id: this.id,
      name: this.name,
      predictions: preds,
      scores: {},
      metrics: { isBaseline: true },
      explanation: `Mô hình đối chứng ngẫu nhiên đồng đều (Uniform Random Baseline) cùng quy mô lựa chọn (${topN} số). Dùng để kiểm định xem các mô hình định lượng có thực sự tạo ra alpha so với chọn ngẫu nhiên hay không.`
    };
  }
};

export const BacktestEngine = {
  algorithms: [
    EnsembleAlgorithm,
    MarkovAlgorithm,
    PoissonAlgorithm,
    MonteCarloAlgorithm,
    FrequencyGapAlgorithm,
    MovingAverageAlgorithm,
    ClusteringAlgorithm,
    AssociationRulesAlgorithm
  ],
  baselineAlgorithm: RandomBaselineAlgorithm,

  /**
   * Chạy dò kết quả cho một ngày cụ thể (Single Date Backtest)
   */
  runSingleDateBacktest(fullHistory, targetDate, options = {}) {
    const isVietlott = options.isVietlott || false;
    const stationOrGame = options.stationOrGame || 'tphcm';

    // 1. Tìm kết quả thực tế của ngày targetDate
    let actualDraw = null;
    if (isVietlott) {
      actualDraw = fullHistory.find(d => d.date === targetDate);
    } else {
      actualDraw = fullHistory.find(d => d.date === targetDate && (stationOrGame === 'all' || d.stationId === stationOrGame));
    }

    if (!actualDraw) {
      return {
        success: false,
        message: `Không tìm thấy bảng kết quả thực tế ngày ${targetDate}`
      };
    }

    // 2. Nghiêm ngặt loại trừ Lookahead Bias: Chỉ lấy dữ liệu TRƯỚC ngày targetDate (so sánh chuỗi ISO chuẩn)
    const trainingData = fullHistory.filter(d => typeof d.date === 'string' && d.date < targetDate);

    if (trainingData.length < 1) {
      return {
        success: false,
        message: `Không đủ dữ liệu lịch sử trước ngày ${targetDate} để huấn luyện mô hình (cần tối thiểu 1 kỳ trước đó).`
      };
    }

    // 3. Chuẩn bị kết quả thực tế để đối chiếu
    let actualWinningNumbers = [];
    let specialPrize = null;
    let headTailStats = null;

    if (isVietlott) {
      actualWinningNumbers = actualDraw.winningNumbers || [];
    } else {
      actualWinningNumbers = actualDraw.lottoPairs || [];
      specialPrize = actualDraw.prizes && actualDraw.prizes.special ? actualDraw.prizes.special[0] : null;
      headTailStats = actualDraw.headTail;
    }

    // 4. Chạy từng thuật toán để sinh dự đoán và đối soát
    const algoResults = [];
    const predOptions = { ...options, targetDrawDate: targetDate };

    this.algorithms.forEach(algo => {
      try {
        const predResult = algo.predict(trainingData, predOptions);
        const predictions = predResult.predictions || [];

        // Đếm số lượng trúng và chi tiết
        let hitCount = 0;
        let totalOccurrences = 0; // Đếm số nháy (đối với XSMN)
        const hitDetails = [];

        predictions.forEach(p => {
          const predStr = String(p);
          const predNum = Number(p);

          if (isVietlott) {
            // Đối với Vietlott: so khớp bóng số
            const matched = actualWinningNumbers.includes(predNum);
            if (matched) {
              hitCount++;
              hitDetails.push({ num: p, hits: 1, isSpecial: false });
            }
          } else {
            // Đối với XSMN: so khớp lô 2 số cuối (18 giải)
            const occurrences = actualWinningNumbers.filter(n => String(n) === predStr).length;
            const isSpecialHit = specialPrize && specialPrize.endsWith(predStr);

            if (occurrences > 0) {
              hitCount++;
              totalOccurrences += occurrences;
              hitDetails.push({
                num: p,
                hits: occurrences,
                isSpecial: isSpecialHit
              });
            }
          }
        });

        const totalPredicted = predictions.length;
        const hitRate = totalPredicted > 0 ? Math.round((hitCount / totalPredicted) * 1000) / 10 : 0;

        algoResults.push({
          algoId: algo.id,
          algoName: algo.name,
          predictions,
          hitCount,
          totalOccurrences,
          totalPredicted,
          hitRate,
          hitDetails,
          explanation: predResult.explanation
        });
      } catch (err) {
        console.error(`Lỗi backtest thuật toán ${algo.id}:`, err);
      }
    });

    // 5. Chạy đối chứng ngẫu nhiên (Random Baseline) trên cùng kỳ và cùng số lượng dự đoán
    let baselineResult = null;
    try {
      const basePred = this.baselineAlgorithm.predict(trainingData, predOptions);
      const baseNums = basePred.predictions || [];
      let baseHits = 0;
      baseNums.forEach(p => {
        if (isVietlott) {
          if (actualWinningNumbers.includes(Number(p))) baseHits++;
        } else {
          if (actualWinningNumbers.some(n => String(n) === String(p))) baseHits++;
        }
      });
      const baseHitRate = baseNums.length > 0 ? Math.round((baseHits / baseNums.length) * 1000) / 10 : 0;
      baselineResult = {
        name: this.baselineAlgorithm.name,
        predictions: baseNums,
        hitCount: baseHits,
        hitRate: baseHitRate
      };
    } catch (e) {}

    // Sắp xếp thuật toán theo tỷ lệ trúng cao nhất trong ngày này
    algoResults.sort((a, b) => b.hitRate - a.hitRate || b.totalOccurrences - a.totalOccurrences);

    return {
      success: true,
      targetDate,
      stationOrGame,
      actualDraw,
      trainingDataCount: trainingData.length,
      algoResults,
      baseline: baselineResult,
      summary: {
        bestAlgo: algoResults[0] ? algoResults[0].algoName : 'N/A',
        bestHitRate: algoResults[0] ? algoResults[0].hitRate : 0,
        randomBaselineHitRate: baselineResult ? baselineResult.hitRate : 0,
        averageHitRate: Math.round((algoResults.reduce((acc, c) => acc + c.hitRate, 0) / (algoResults.length || 1)) * 10) / 10
      }
    };
  },

  /**
   * Chạy kiểm định hàng loạt (Walk-Forward Batch Backtesting) qua nhiều kỳ để lập bảng xếp hạng thuật toán
   */
  runBatchBacktest(fullHistory, options = {}, numDraws = 20) {
    const isVietlott = options.isVietlott || false;
    const sortedHistory = [...fullHistory].sort((a, b) => (b.date > a.date ? 1 : (b.date < a.date ? -1 : 0)));
    const testDraws = sortedHistory.slice(0, numDraws);

    const statsByAlgo = {};
    this.algorithms.forEach(algo => {
      statsByAlgo[algo.id] = {
        id: algo.id,
        name: algo.name,
        totalDrawsTested: 0,
        totalPredictions: 0,
        totalHits: 0,
        totalOccurrences: 0,
        hitRates: [],
        bestHitRate: 0,
        specialMatches: 0
      };
    });

    let baselineTotalHits = 0;
    let baselineHitRates = [];

    // Duyệt qua từng kỳ trong dải kiểm định (Walk-forward: mỗi bước chỉ train trên dữ liệu trước kỳ đó)
    testDraws.forEach(draw => {
      const singleRes = this.runSingleDateBacktest(fullHistory, draw.date, options);
      if (singleRes.success && singleRes.algoResults) {
        singleRes.algoResults.forEach(item => {
          const s = statsByAlgo[item.algoId];
          if (s) {
            s.totalDrawsTested++;
            s.totalPredictions += item.totalPredicted;
            s.totalHits += item.hitCount;
            s.totalOccurrences += item.totalOccurrences;
            s.hitRates.push(item.hitRate);
            if (item.hitRate > s.bestHitRate) s.bestHitRate = item.hitRate;
            if (item.hitDetails.some(h => h.isSpecial)) s.specialMatches++;
          }
        });

        if (singleRes.baseline) {
          baselineTotalHits += singleRes.baseline.hitCount;
          baselineHitRates.push(singleRes.baseline.hitRate);
        }
      }
    });

    const baselineAvgHitRate = baselineHitRates.length > 0
      ? Math.round((baselineHitRates.reduce((a, b) => a + b, 0) / baselineHitRates.length) * 10) / 10
      : (isVietlott ? 13.3 : 18.0);

    // Tổng hợp điểm số và xếp hạng
    const leaderboard = Object.values(statsByAlgo).map(s => {
      const avgHitRate = s.hitRates.length > 0
        ? Math.round((s.hitRates.reduce((a, b) => a + b, 0) / s.hitRates.length) * 10) / 10
        : 0;

      const baselineDiff = Math.round((avgHitRate - baselineAvgHitRate) * 10) / 10;

      return {
        id: s.id,
        name: s.name,
        drawsTested: s.totalDrawsTested,
        avgHitRate,
        bestHitRate: s.bestHitRate,
        totalHits: s.totalHits,
        totalOccurrences: s.totalOccurrences,
        specialMatches: s.specialMatches,
        baselineHitRate: baselineAvgHitRate,
        baselineDiff,
        exceedsBaseline: avgHitRate >= baselineAvgHitRate,
        // Điểm đánh giá tổng hợp (Composite Score)
        compositeScore: Math.round((avgHitRate * 0.7 + s.bestHitRate * 0.2 + s.specialMatches * 5) * 10) / 10
      };
    });

    leaderboard.sort((a, b) => b.compositeScore - a.compositeScore || b.avgHitRate - a.avgHitRate);

    return {
      success: true,
      drawsTestedCount: testDraws.length,
      baseline: {
        name: "Chuẩn Ngẫu Nhiên",
        avgHitRate: baselineAvgHitRate,
        totalHits: baselineTotalHits
      },
      leaderboard
    };
  }
};

