  },

  /**
   * Chạy kiểm định hàng loạt (Batch Backtesting) qua nhiều kỳ để lập bảng xếp hạng thuật toán
   */
  runBatchBacktest(fullHistory, options = {}, numDraws = 20) {
    const isVietlott = options.isVietlott || false;
    const sortedHistory = [...fullHistory].sort((a, b) => new Date(b.date) - new Date(a.date));
    const testDraws = sortedHistory.slice(0, numDraws);

    const statsByAlgo = {};
    this.algorithms.forEach(algo => {
      statsByAlgo[algo.id] = {
        id: algo.id,
        name: algo.name,
        totalDrawsTested: 0,
        totalPredictions: 0,
        totalHits: 0,
        totalOccurrences: 0,
        hitRates: [],
        bestHitRate: 0,
        specialMatches: 0
      };
    });

    // Duyệt qua từng kỳ trong dải kiểm định
    testDraws.forEach(draw => {
      const singleRes = this.runSingleDateBacktest(fullHistory, draw.date, options);
      if (singleRes.success && singleRes.algoResults) {
        singleRes.algoResults.forEach(item => {
          const s = statsByAlgo[item.algoId];
          if (s) {
            s.totalDrawsTested++;
            s.totalPredictions += item.totalPredicted;
            s.totalHits += item.hitCount;
            s.totalOccurrences += item.totalOccurrences;
            s.hitRates.push(item.hitRate);
            if (item.hitRate > s.bestHitRate) s.bestHitRate = item.hitRate;
            if (item.hitDetails.some(h => h.isSpecial)) s.specialMatches++;
          }
        });
      }
    });

    // Tổng hợp điểm số và xếp hạng
    const leaderboard = Object.values(statsByAlgo).map(s => {
      const avgHitRate = s.hitRates.length > 0
        ? Math.round((s.hitRates.reduce((a, b) => a + b, 0) / s.hitRates.length) * 10) / 10
        : 0;

      return {
        id: s.id,
        name: s.name,
        drawsTested: s.totalDrawsTested,
        avgHitRate,
        bestHitRate: s.bestHitRate,
        totalHits: s.totalHits,
        totalOccurrences: s.totalOccurrences,
        specialMatches: s.specialMatches,
        // Điểm đánh giá tổng hợp (Composite Score)
        compositeScore: Math.round((avgHitRate * 0.7 + s.bestHitRate * 0.2 + s.specialMatches * 5) * 10) / 10
      };
    });

    leaderboard.sort((a, b) => b.compositeScore - a.compositeScore || b.avgHitRate - a.avgHitRate);

    return {
      success: true,
      drawsTestedCount: testDraws.length,
      leaderboard
    };
  }
};

