  assert(vietlottRes.metrics.aggregationMethod.includes('Soft Voting'), 'Ensemble: Cơ chế tổng hợp xếp hạng là Weighted Soft Voting');
  assert(!vietlottRes.explanation.includes('65 +'), 'Ensemble: Giải thích mô hình không dùng công thức độ tin cậy ảo');

  // 8.4 Xử lý an toàn khi sub-model lỗi hoặc rỗng
  const safeEnsemble = EnsembleAlgorithm.predict([], { isVietlott: true, totalBalls: 45, topN: 6 });
  assert(safeEnsemble && safeEnsemble.predictions && safeEnsemble.predictions.length === 6, 'Ensemble xử lý an toàn khi dữ liệu rỗng');

  // TEST 9: Kiểm Định Chống Rò Rỉ Thời Gian (Strict Walk-forward Anti-leakage)
  console.log('\n9. Kiểm thử Nghiêm Ngặt Chống Rò Rỉ Thời Gian (Anti-leakage Across Folds):');
  let zeroLeakage = true;
  testDrawsLoop:
  for (let k = 0; k < Math.min(10, megaHistory.length - 1); k++) {
    const targetDateStr = megaHistory[k].date;
    const trainSubset = megaHistory.filter(d => typeof d.date === 'string' && d.date < targetDateStr);
    for (const d of trainSubset) {
      if (d.date >= targetDateStr) {
        zeroLeakage = false;
        break testDrawsLoop;
      }
    }
  }
  assert(zeroLeakage, 'Kiểm định Walk-Forward: 100% các kỳ trong tập train có ngày nhỏ hơn kỳ mục tiêu (0% Leakage)');

  // TEST 10: Kiểm Định Không Còn KPI / Số Liệu Hardcode
  console.log('\n10. Kiểm tra Loại Bỏ Toàn Bộ Số Liệu KPI Hardcode:');
  const appJsContent = fs.readFileSync(path.join(__dirname, '../js/app.js'), 'utf-8');
  const hasHardcodedConfidence = appJsContent.includes("'88.5%' : '91.2%'");
  const hasHardcodedHitrate = appJsContent.includes("'38.2%' : '66.7%'");
  assert(!hasHardcodedConfidence, 'app.js: Không còn confidence hardcode 88.5% : 91.2%');
  assert(!hasHardcodedHitrate, 'app.js: Không còn hitrate hardcode 38.2% : 66.7%');

  console.log('\n========================================================');
  console.log(` KẾT QUẢ TỔNG HỢP: ${passedCount} PASS, ${failedCount} FAIL`);
  console.log('========================================================');

  if (failedCount > 0) {
    process.exit(1);
  }
}

