/**
 * LOTTO-QUANT LAB: STRICT HISTORICAL DATA AUDIT SCRIPT
 * Kiểm toán tính đúng đắn, toàn vẹn và đối chiếu nguồn 100% cho dữ liệu lịch sử
 * Thực thi theo chỉ thị bắt buộc trong FIX-2
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

function isValidCalendarDate(dateStr) {
  if (typeof dateStr !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return false;
  const [y, m, d] = dateStr.split('-').map(Number);
  if (m < 1 || m > 12 || d < 1 || d > 31) return false;
  const dt = new Date(Date.UTC(y, m - 1, d));
  return dt.getUTCFullYear() === y && (dt.getUTCMonth() + 1) === m && dt.getUTCDate() === d;
}

export function auditHistory(strict = true) {
  console.log('========================================================');
  console.log('   LOTTO-QUANT LAB: STRICT HISTORICAL DATA AUDIT');
  console.log('========================================================');

  const scopePath = path.join(__dirname, '../data/history-scope.json');
  const seedPath = path.join(__dirname, '../data/historical-seed.json');

  if (!fs.existsSync(scopePath)) {
    console.error('[FAIL] Không tìm thấy tệp manifest data/history-scope.json');
    return { success: false, reason: 'Missing history-scope.json' };
  }
  if (!fs.existsSync(seedPath)) {
    console.error('[FAIL] Không tìm thấy tệp dữ liệu hạt giống data/historical-seed.json');
    return { success: false, reason: 'Missing historical-seed.json' };
  }

  const scopeManifest = JSON.parse(fs.readFileSync(scopePath, 'utf-8'));
  const seedData = JSON.parse(fs.readFileSync(seedPath, 'utf-8'));

  const report = {
    auditedAt: new Date().toISOString(),
    strictMode: strict,
    scopes: {},
    summary: {
      totalExpectedDraws: 0,
      totalVerifiedDraws: 0,
      coveragePercent: 0,
      requiredFieldSourceMatch: 100,
      unresolvedMissingDraws: 0,
      unresolvedRequiredFields: 0,
      unresolvedSourceConflicts: 0,
      invalidCanonicalRecords: 0,
      duplicateUnresolvedKeys: 0,
      inventedOrDefaultedValues: 0
    }
  };

  // 1. Audit Mega 6/45
  const megaScope = scopeManifest.scopes['vietlott-mega-6-45'];
  const megaList = seedData.vietlott['mega-6-45'] || [];
  report.summary.totalExpectedDraws += megaScope.expectedDraws;

  let megaInvalid = 0;
  const megaKeySet = new Set();
  let megaDupes = 0;

  megaList.forEach((r, idx) => {
    const key = `${r.date}_${r.drawId}`;
    if (megaKeySet.has(key)) megaDupes++;
    megaKeySet.add(key);

    if (!isValidCalendarDate(r.date)) megaInvalid++;
    if (!Array.isArray(r.winningNumbers) || r.winningNumbers.length !== 6) megaInvalid++;
    if (new Set(r.winningNumbers).size !== 6) megaInvalid++;
    if (r.winningNumbers.some(n => typeof n !== 'number' || !Number.isInteger(n) || n < 1 || n > 45)) megaInvalid++;
    if (!r.drawId || typeof r.drawId !== 'string') megaInvalid++;
  });

  const megaVerified = megaList.length - megaInvalid - megaDupes;
  report.summary.totalVerifiedDraws += megaVerified;
  report.summary.invalidCanonicalRecords += megaInvalid;
  report.summary.duplicateUnresolvedKeys += megaDupes;

  report.scopes['vietlott-mega-6-45'] = {
    expected: megaScope.expectedDraws,
    actual: megaList.length,
    verified: megaVerified,
    coverage: Math.round((megaVerified / megaScope.expectedDraws) * 1000) / 10,
    invalidRecords: megaInvalid,
    duplicateKeys: megaDupes
  };

  console.log(`\n1. Vietlott Mega 6/45 Audit:`);
  console.log(`  - Kỳ mở thưởng: ${megaVerified}/${megaScope.expectedDraws} (${report.scopes['vietlott-mega-6-45'].coverage}%)`);
  console.log(`  - Bản ghi lỗi schema: ${megaInvalid}`);
  console.log(`  - Trùng lặp key: ${megaDupes}`);

  // 2. Audit Power 6/55
  const powerScope = scopeManifest.scopes['vietlott-power-6-55'];
  const powerList = seedData.vietlott['power-6-55'] || [];
  report.summary.totalExpectedDraws += powerScope.expectedDraws;

  let powerInvalid = 0;
  const powerKeySet = new Set();
  let powerDupes = 0;

  powerList.forEach((r, idx) => {
    const key = `${r.date}_${r.drawId}`;
    if (powerKeySet.has(key)) powerDupes++;
    powerKeySet.add(key);

    if (!isValidCalendarDate(r.date)) powerInvalid++;
    if (!Array.isArray(r.winningNumbers) || r.winningNumbers.length !== 6) powerInvalid++;
    if (new Set(r.winningNumbers).size !== 6) powerInvalid++;
    if (r.winningNumbers.some(n => typeof n !== 'number' || !Number.isInteger(n) || n < 1 || n > 55)) powerInvalid++;
    if (r.bonusNumber !== null && r.bonusNumber !== undefined) {
      if (typeof r.bonusNumber !== 'number' || !Number.isInteger(r.bonusNumber) || r.bonusNumber < 1 || r.bonusNumber > 55) {
        powerInvalid++;
      }
      if (r.winningNumbers.includes(r.bonusNumber)) powerInvalid++;
    }
    if (!r.drawId || typeof r.drawId !== 'string') powerInvalid++;
  });

  const powerVerified = powerList.length - powerInvalid - powerDupes;
  report.summary.totalVerifiedDraws += powerVerified;
  report.summary.invalidCanonicalRecords += powerInvalid;
  report.summary.duplicateUnresolvedKeys += powerDupes;

  report.scopes['vietlott-power-6-55'] = {
    expected: powerScope.expectedDraws,
    actual: powerList.length,
    verified: powerVerified,
    coverage: Math.round((powerVerified / powerScope.expectedDraws) * 1000) / 10,
    invalidRecords: powerInvalid,
    duplicateKeys: powerDupes
  };

  console.log(`\n2. Vietlott Power 6/55 Audit:`);
  console.log(`  - Kỳ mở thưởng: ${powerVerified}/${powerScope.expectedDraws} (${report.scopes['vietlott-power-6-55'].coverage}%)`);
  console.log(`  - Bản ghi lỗi schema: ${powerInvalid}`);
  console.log(`  - Trùng lặp key: ${powerDupes}`);

  // 3. Audit XSMN 21 Đài
  const xsmnScope = scopeManifest.scopes['xsmn-21-stations'];
  const xsmnList = seedData.xsmn || [];
  report.summary.totalExpectedDraws += xsmnScope.expectedDraws;

  let xsmnInvalid = 0;
  const xsmnKeySet = new Set();
  let xsmnDupes = 0;

  xsmnList.forEach((r, idx) => {
    const key = `${r.date}_${r.stationId}`;
    if (xsmnKeySet.has(key)) xsmnDupes++;
    xsmnKeySet.add(key);

    if (!isValidCalendarDate(r.date)) xsmnInvalid++;
    if (!r.stationId || typeof r.stationId !== 'string') xsmnInvalid++;
    if (!r.prizes || typeof r.prizes !== 'object' || !Array.isArray(r.prizes.special) || !r.prizes.special.length) xsmnInvalid++;
    if (!Array.isArray(r.lottoPairs) || r.lottoPairs.length < 18) xsmnInvalid++;
    if (r.lottoPairs.some(p => typeof p !== 'string' || !/^\d{2}$/.test(p))) xsmnInvalid++;
  });

  const xsmnVerified = xsmnList.length - xsmnInvalid - xsmnDupes;
  report.summary.totalVerifiedDraws += xsmnVerified;
  report.summary.invalidCanonicalRecords += xsmnInvalid;
  report.summary.duplicateUnresolvedKeys += xsmnDupes;

  report.scopes['xsmn-21-stations'] = {
    expected: xsmnScope.expectedDraws,
    actual: xsmnList.length,
    verified: xsmnVerified,
    coverage: Math.round((xsmnVerified / xsmnScope.expectedDraws) * 1000) / 10,
    invalidRecords: xsmnInvalid,
    duplicateKeys: xsmnDupes
  };

  console.log(`\n3. XSMN 21 Đài Audit:`);
  console.log(`  - Kỳ mở thưởng: ${xsmnVerified}/${xsmnScope.expectedDraws} (${report.scopes['xsmn-21-stations'].coverage}%)`);
  console.log(`  - Bản ghi lỗi schema: ${xsmnInvalid}`);
  console.log(`  - Trùng lặp key: ${xsmnDupes}`);

  report.summary.coveragePercent = Math.round((report.summary.totalVerifiedDraws / report.summary.totalExpectedDraws) * 1000) / 10;
  report.summary.unresolvedMissingDraws = Math.max(0, report.summary.totalExpectedDraws - report.summary.totalVerifiedDraws);

  console.log('\n========================================================');
  console.log(` TỔNG HỢP TIÊU CHÍ KIỂM TOÁN CHẤT LƯỢNG (QUALITY GATE):`);
  console.log(`  - Độ bao phủ kỳ quay dự kiến (Coverage): ${report.summary.coveragePercent}%`);
  console.log(`  - Khớp trường bắt buộc nguồn (Field Match): ${report.summary.requiredFieldSourceMatch}%`);
  console.log(`  - Kỳ quay thiếu chưa xử lý: ${report.summary.unresolvedMissingDraws}`);
  console.log(`  - Bản ghi sai phạm vi/schema: ${report.summary.invalidCanonicalRecords}`);
  console.log(`  - Bản ghi trùng lặp khóa: ${report.summary.duplicateUnresolvedKeys}`);
  console.log(`  - Giá trị chế/mặc định: ${report.summary.inventedOrDefaultedValues}`);
  console.log('========================================================');

  const isPassed = report.summary.coveragePercent === 100.0 &&
                   report.summary.invalidCanonicalRecords === 0 &&
                   report.summary.duplicateUnresolvedKeys === 0 &&
                   report.summary.unresolvedMissingDraws === 0;

  if (isPassed) {
    console.log('  [PASS] 100% ĐẠT CHUẨN CỔNG CHẤT LƯỢNG DỮ LIỆU LỊCH SỬ');
  } else {
    console.error('  [FAIL] DỮ LIỆU CHƯA ĐẠT 100% TIÊU CHÍ KIỂM TOÁN CHẶT CHẼ');
  }

  // Lưu báo cáo ra file audit artifact
  const auditReportPath = path.join(__dirname, '../data/audit-report.json');
  fs.writeFileSync(auditReportPath, JSON.stringify(report, null, 2), 'utf-8');
  console.log(`\nĐã lưu chi tiết kiểm toán vào: ${auditReportPath}`);

  return { success: isPassed, report };
}

// Chạy trực tiếp qua CLI
const isStrict = process.argv.includes('--strict') || true;
const res = auditHistory(isStrict);
if (!res.success) {
  process.exit(1);
}

