    if (ballMatches.length >= 6) {
      const winningNumbers = ballMatches.slice(0, 6).sort((a, b) => a - b);
      const bonusNumber = (gameType === 'power-6-55' && ballMatches.length > 6) ? ballMatches[6] : null;

      results.push({
        date: dateFormatted,
        drawDateRaw: dateRaw,
        gameType,
        drawId,
