        bonusNumber,
        jackpotEst
      });
    }
  }

  // Loại bỏ các kỳ trùng lặp nếu có
  const unique = [];
  const seen = new Set();
  results.forEach(r => {
    const key = `${r.date}_${r.drawId}`;
    if (!seen.has(key)) {
      seen.add(key);
      unique.push(r);
    }
  });

  return unique.sort((a, b) => new Date(b.date) - new Date(a.date));
