        explanation: 'Chưa đủ dữ liệu lịch sử để thực hiện phân tích xác suất Poisson.'
      };
    }

    const counts = {};
    const minNum = isVietlott ? 1 : 0;

    for (let i = minNum; i <= maxNum; i++) {
      const key = isVietlott ? i : (i < 10 ? '0' + i : '' + i);
      counts[key] = 0;
    }

    // Đếm tần suất trong N kỳ gần nhất
    const recentDraws = historyData.slice(0, nDraws);
    recentDraws.forEach(draw => {
      const nums = isVietlott ? (draw.winningNumbers || []) : (draw.lottoPairs || []);
      nums.forEach(n => {
        const key = isVietlott ? Number(n) : String(n);
        if (counts[key] !== undefined) {
          counts[key]++;
        }
      });
    });

    // Tính lambda và xác suất Poisson P(X >= 1) = 1 - e^(-λ)
    const scores = {};
    const stats = [];

    for (let i = minNum; i <= maxNum; i++) {
      const key = isVietlott ? i : (i < 10 ? '0' + i : '' + i);
      const lambda = counts[key] / nDraws;
      const probAtLeastOne = 1 - Math.exp(-lambda);
      const score = Math.round(probAtLeastOne * 1000) / 10; // Chuyển thành % (0 - 100)

      scores[key] = score;
      stats.push({
        num: key,
        count: counts[key],
        lambda: Math.round(lambda * 1000) / 1000,
        score
      });
    }

    // Sắp xếp giảm dần theo điểm số xác suất
    stats.sort((a, b) => b.score - a.score || a.num - b.num);
