predict(historyData, options = {}) {
  const isVietlott = options.isVietlott || false;
  const maxNum = isVietlott ? (options.totalBalls || 45) : 99;
  const minNum = isVietlott ? 1 : 0;
  const topN = options.topN || (isVietlott ? 6 : 5);

  // Xử lý nghiêm ngặt khi thiếu dữ liệu lịch sử
  if (!historyData || !Array.isArray(historyData) || historyData.length === 0) {
    return {
      status: 'insufficient-data',
      id: this.id,
      name: this.name,
      predictions: [],
      specialPrize: null,
      scores: {},
      subResults: [],
      metrics: {
        totalAlgorithmsCombined: 0,
        consensusRatio: "0%",
        consensusLevel: "0%",
        confidenceScore: "0%",
        aggregationMethod: "Weighted Normalized Soft Voting",
        topRanking: []
      },
      explanation: 'Chưa đủ dữ liệu lịch sử để thực hiện dự đoán tổng hợp Ensemble.'
    };
  }

  // 1. Chạy từng thuật toán con độc lập và lọc các model hợp lệ
  const subResults = [];
  this.subAlgorithms.forEach(item => {
    try {
      const res = item.algo.predict(historyData, options);
      subResults.push({
        id: item.algo.id,
        name: item.algo.name,
        weight: item.weight,
        status: res?.status || (res?.predictions?.length ? 'ok' : 'insufficient-data'),
        result: res
      });
    } catch (err) {
      console.error(`Lỗi khi chạy thuật toán ${item.algo.id}:`, err);
      subResults.push({
        id: item.algo.id,
        name: item.algo.name,
        weight: item.weight,
        status: 'error',
        error: err.message,
        result: null
      });
    }
  });

  // Lọc các model hợp lệ (phải có trạng thái 'ok' và có scores)
  const validSubResults = subResults.filter(sr => sr.status === 'ok' && sr.result && sr.result.scores);
  if (validSubResults.length === 0) {
    return {
      status: 'insufficient-data',
      id: this.id,
      name: this.name,
      predictions: [],
      specialPrize: null,
      scores: {},
      subResults,
      metrics: {
        totalAlgorithmsCombined: 0,
        consensusRatio: "0%",
        consensusLevel: "0%",
        confidenceScore: "0%",
        aggregationMethod: "Weighted Normalized Soft Voting",
        topRanking: []
      },
      explanation: 'Không có thuật toán thành phần nào đủ điều kiện tạo dự đoán từ tập dữ liệu hiện tại.'
    };
  }

  // 2. Chuẩn hóa thang điểm nội bộ (Per-Model Min-Max Normalization về [0, 100])
  // Đảm bảo không model nào chi phối chỉ vì thang đo điểm tự nhiên khác nhau
  const normalizedModelScores = validSubResults.map(item => {
    const rawScores = item.result.scores || {};
    const scoreVals = [];
    for (let i = minNum; i <= maxNum; i++) {
      const keyPrimary = isVietlott ? i : (i < 10 ? '0' + i : '' + i);
      const keyAlt = isVietlott ? String(i) : Number(i);
      const s = rawScores[keyPrimary] !== undefined ? Number(rawScores[keyPrimary]) : (rawScores[keyAlt] !== undefined ? Number(rawScores[keyAlt]) : NaN);
      if (!isNaN(s) && isFinite(s)) {
        scoreVals.push(s);
      }
    }

    const minVal = scoreVals.length > 0 ? Math.min(...scoreVals) : 0;
    const maxVal = scoreVals.length > 0 ? Math.max(...scoreVals) : 0;
    const range = maxVal - minVal;

    const normMap = {};
    for (let i = minNum; i <= maxNum; i++) {
      const keyPrimary = isVietlott ? i : (i < 10 ? '0' + i : '' + i);
      const keyAlt = isVietlott ? String(i) : Number(i);
      const s = rawScores[keyPrimary] !== undefined ? Number(rawScores[keyPrimary]) : (rawScores[keyAlt] !== undefined ? Number(rawScores[keyAlt]) : NaN);
      if (!isNaN(s) && isFinite(s)) {
        normMap[keyPrimary] = range > 0 ? ((s - minVal) / range) * 100 : 50;
      } else {
        normMap[keyPrimary] = 0;
      }
    }

    const weight = (typeof item.weight === 'number' && item.weight > 0 && isFinite(item.weight)) ? item.weight : 0;
    return {
      item,
      weight,
      normMap,
      preds: new Set((item.result.predictions || []).map(p => isVietlott ? Number(p) : String(p).padStart(2, '0')))
    };
  }).filter(m => m.weight > 0);

  const totalWeight = normalizedModelScores.reduce((sum, m) => sum + m.weight, 0);

  // 3. Tính điểm số tổng hợp Weighted Soft Voting
  const ensembleScores = {};
  const voteCounts = {};

  for (let i = minNum; i <= maxNum; i++) {
    const key = isVietlott ? i : (i < 10 ? '0' + i : '' + i);
    let weightedSum = 0;
    let votes = 0;

    normalizedModelScores.forEach(m => {
      weightedSum += (m.normMap[key] || 0) * m.weight;
      if (m.preds.has(key)) {
        votes++;
      }
    });

    const finalNormScore = totalWeight > 0 ? Math.round((weightedSum / totalWeight) * 10) / 10 : 0;
    ensembleScores[key] = finalNormScore;
    voteCounts[key] = votes;
  }

  const stats = [];
  for (let i = minNum; i <= maxNum; i++) {
    const key = isVietlott ? i : (i < 10 ? '0' + i : '' + i);
