  // 4. Tính Mức Đồng Thuận Thực Tế Giữa Các Mô Hình (% Consensus Level)
  const topVotes = stats.slice(0, topN).reduce((acc, cur) => acc + cur.votes, 0);
  const maxPossibleVotes = topN * Math.max(normalizedModelScores.length, 1);
  const consensusRatio = maxPossibleVotes > 0 ? (topVotes / maxPossibleVotes) : 0;
  const consensusPercent = Math.round(consensusRatio * 1000) / 10;

