predict(historyData, options = {}) {
  const isVietlott = options.isVietlott || false;
  const maxNum = isVietlott ? (options.totalBalls || 45) : 99;
  const minNum = isVietlott ? 1 : 0;
  const topN = options.topN || (isVietlott ? 6 : 5);

  // 1. Chạy từng thuật toán con độc lập
  const subResults = [];
  this.subAlgorithms.forEach(item => {
    try {
      const res = item.algo.predict(historyData, options);
      subResults.push({
        id: item.algo.id,
        name: item.algo.name,
        weight: item.weight,
        result: res
      });
    } catch (err) {
      console.error(`Lỗi khi chạy thuật toán ${item.algo.id}:`, err);
    }
  });

  // 2. Tính điểm số tổng hợp trọng số: E(i) = ∑ [w_k * S_k(i)]
  const ensembleScores = {};
  const voteCounts = {}; // Đếm xem có bao nhiêu thuật toán xếp số này vào top

  for (let i = minNum; i <= maxNum; i++) {
    const key = isVietlott ? i : (i < 10 ? '0' + i : '' + i);
    ensembleScores[key] = 0;
    voteCounts[key] = 0;
  }

  let totalWeight = 0;
  subResults.forEach(item => {
    const weight = (typeof item.weight === 'number' && item.weight > 0 && isFinite(item.weight)) 
      ? item.weight 
      : 0.1;
    totalWeight += weight;
    const scores = (item.result && item.result.scores) || {};
    const preds = new Set(item.result && item.result.predictions ? item.result.predictions : []);

    for (let i = minNum; i <= maxNum; i++) {
      const key = isVietlott ? i : (i < 10 ? '0' + i : '' + i);
      let s = Number(scores[key]);
      if (isNaN(s) || !isFinite(s)) s = 50; // Điểm trung tính an toàn
      ensembleScores[key] += s * weight;

      if (preds.has(key) || preds.has(Number(key)) || preds.has(String(key))) {
        voteCounts[key]++;
      }
    }
  });

  // Chuẩn hóa điểm số (Weighted Soft Voting)
  const stats = [];
  for (let i = minNum; i <= maxNum; i++) {
    const key = isVietlott ? i : (i < 10 ? '0' + i : '' + i);
    const normalizedScore = totalWeight > 0 ? (ensembleScores[key] / totalWeight) : 50;
    const finalScore = Math.round(normalizedScore * 10) / 10;
    ensembleScores[key] = finalScore;

    stats.push({
      num: key,
      score: finalScore,
      votes: voteCounts[key] || 0
    });
  }

  // Sắp xếp nhất quán: Xếp theo Điểm tổng hợp có trọng số (Weighted Soft Voting), số phiếu bầu làm tiêu chí phụ
  stats.sort((a, b) => b.score - a.score || b.votes - a.votes || a.num - b.num);
  const topCandidates = stats.slice(0, topN).map(s => s.num);

  // 3. Tính Mức Đồng Thuận Thực Tế Giữa Các Mô Hình (% Consensus Level)
  const topVotes = stats.slice(0, topN).reduce((acc, cur) => acc + cur.votes, 0);
  const maxPossibleVotes = topN * Math.max(subResults.length, 1);
  const consensusRatio = maxPossibleVotes > 0 ? (topVotes / maxPossibleVotes) : 0;
  // Tỷ lệ phần trăm đồng thuận thực tế (không cộng thêm offset ảo)
  const consensusPercent = Math.round(consensusRatio * 1000) / 10;

  // 4. Dự đoán Dãy 6 Số Giải Đặc Biệt (XSMN Positional Quant Model)
  const specialPrize = !isVietlott ? this.predictSpecialPrize(historyData, topCandidates) : null;

  return {
    id: this.id,
    name: this.name,
    predictions: topCandidates,
    specialPrize,
    scores: ensembleScores,
    subResults,
    metrics: {
      totalAlgorithmsCombined: subResults.length,
      consensusRatio: consensusPercent + "%",
      consensusLevel: consensusPercent + "%",
