      const s = String(options.targetDrawDate) + (isVietlott ? '_v' : '_x');
      for (let i = 0; i < s.length; i++) baseSeed = ((baseSeed << 5) - baseSeed + s.charCodeAt(i)) | 0;
    }

    const generateOneSample = (seedOffset) => {
      let s = ((baseSeed + seedOffset) >>> 0) || 1;
      const rng = () => {
        s = (s + 0x6D2B79F5) | 0;
        let t = Math.imul(s ^ (s >>> 15), 1 | s);
        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
        return ((t >>> 0) / 4294967296);
      };

      const set = [];
      while (set.length < topN) {
        const val = isVietlott
          ? Math.floor(rng() * (maxNum - minNum + 1)) + minNum
          : String(Math.floor(rng() * 100)).padStart(2, '0');
        if (!set.includes(val)) {
          set.push(val);
        }
      }
      return set;
    };

    // Tạo mẫu đại diện chính (replicate 0) và tập phân phối
    const primaryPreds = generateOneSample(0);
    const replicateSamples = [];
    for (let r = 0; r < replicates; r++) {
      replicateSamples.push(generateOneSample(r));
    }

    return {
      status: 'ok',
      id: this.id,
      name: this.name,
      predictions: primaryPreds,
      replicateSamples,
      scores: {},
