    let baselineTotalHits = 0;
    let baselineHitRates = [];
    let successfulFolds = 0;

    // Duyệt qua từng kỳ trong dải kiểm định (Walk-forward: mỗi bước chỉ train trên dữ liệu trước kỳ đó)
    testDraws.forEach(draw => {
      const singleRes = this.runSingleDateBacktest(fullHistory, draw.date, options);
      if (singleRes.success && singleRes.algoResults) {
        successfulFolds++;
        singleRes.algoResults.forEach(item => {
          const s = statsByAlgo[item.algoId];
          if (s) {
            s.totalDrawsTested++;
            s.totalPredictions += item.totalPredicted;
            s.totalHits += item.hitCount;
            s.totalOccurrences += item.totalOccurrences;
            s.hitRates.push(item.hitRate);
            if (item.hitRate > s.bestHitRate) s.bestHitRate = item.hitRate;
            if (item.hitDetails.some(h => h.isSpecial)) s.specialMatches++;
          }
        });

        if (singleRes.baseline) {
          baselineTotalHits += singleRes.baseline.hitCount;
          baselineHitRates.push(singleRes.baseline.hitRate);
        }
      }
    });

    if (successfulFolds === 0) {
      return {
        status: 'insufficient-data',
        success: false,
        drawsRequested: numDraws,
        drawsEligible: testDraws.length,
        drawsTestedCount: 0,
        drawsFailed: testDraws.length,
        baseline: null,
        leaderboard: [],
        message: 'Không đủ kỳ hợp lệ để thực hiện kiểm định hồi quy (0 fold thành công).'
      };
    }

    const baselineAvgHitRate = baselineHitRates.length > 0
      ? Math.round((baselineHitRates.reduce((a, b) => a + b, 0) / baselineHitRates.length) * 10) / 10
      : 0;

    // Tổng hợp điểm số và xếp hạng theo Primary Metric (avgHitRate)
    const leaderboard = Object.values(statsByAlgo).map(s => {
      const avgHitRate = s.hitRates.length > 0
        ? Math.round((s.hitRates.reduce((a, b) => a + b, 0) / s.hitRates.length) * 10) / 10
        : 0;

      const baselineDiff = Math.round((avgHitRate - baselineAvgHitRate) * 10) / 10;

      return {
        id: s.id,
        name: s.name,
        drawsTested: s.totalDrawsTested,
        avgHitRate,
        bestHitRate: s.bestHitRate,
        totalHits: s.totalHits,
        totalOccurrences: s.totalOccurrences,
        specialMatches: s.specialMatches,
        baselineHitRate: baselineAvgHitRate,
        baselineDiff,
        exceedsBaseline: avgHitRate > baselineAvgHitRate
      };
    });

    // Sắp xếp nhất quán theo Primary Metric (avgHitRate) -> baselineDiff -> totalHits -> id
    leaderboard.sort((a, b) => b.avgHitRate - a.avgHitRate || b.baselineDiff - a.baselineDiff || b.totalHits - a.totalHits || a.id.localeCompare(b.id));

    // Đánh số thứ hạng chính thức rank 1..N
    leaderboard.forEach((item, idx) => {
      item.rank = idx + 1;
      item.isTop1 = idx === 0 && item.drawsTested > 0;
    });

    return {
      status: 'ok',
      success: true,
      drawsRequested: numDraws,
      drawsEligible: testDraws.length,
      drawsTestedCount: successfulFolds,
      drawsFailed: testDraws.length - successfulFolds,
      primaryMetric: 'avgHitRate',
      top1Algorithm: leaderboard[0] || null,
      baseline: {
        name: "Chuẩn Ngẫu Nhiên (Random Baseline)",
        avgHitRate: baselineAvgHitRate,
        totalHits: baselineTotalHits
      },
      leaderboard
    };
  }
};

