  assert(emptyBatch.drawsTestedCount === 0, 'P1: Batch Backtest rỗng có drawsTestedCount === 0');
  assert(emptyBatch.baseline === null, 'P1: Batch Backtest rỗng không tạo baseline giả 13.3/18.0');

