refreshCurrentView() {
  const isVietlott = this.currentMode === 'vietlott';
  const history = isVietlott 
    ? DataService.getVietlottDraws(this.currentVietlottGame, 50)
    : DataService.getXSMNDraws(this.currentStation, 50);

  const latestDraw = history[0];
  const targetInfo = this.calculateNextDrawInfo(this.currentMode, isVietlott ? this.currentVietlottGame : this.currentStation, latestDraw);

  // Tính nhanh ensemble result để đưa Hero Prediction Card vào đầu trang
  let quickPrediction = null;
  try {
    quickPrediction = EnsembleAlgorithm.predict(history, {
      isVietlott,
      totalBalls: isVietlott ? LOTTO_CONFIG.VIETLOTT_GAMES[this.currentVietlottGame].totalBalls : 99,
      topN: isVietlott ? 6 : 5
    });
  } catch (e) {
    console.warn('Lỗi tính quick prediction:', e);
  }

  UIController.renderLiveResult(latestDraw, isVietlott, 'live-result-container', quickPrediction, targetInfo);
  this.updateKPISummary(history, latestDraw, isVietlott);

  // Hiển thị liền mạch toàn bộ các section trên 1 trang cuộn (Single-Page All-in-One)
  this.runAndRenderPredictions();
  this.renderDashboard();

  // Tự động nạp bảng xếp hạng và chuẩn bị dò số kỳ gần nhất
  setTimeout(() => {
    this.executeLeaderboard();
    const backtestSelect = document.getElementById('backtest-date-select');
    if (backtestSelect && backtestSelect.value) {
      this.executeBacktest();
    }
  }, 60);
}

