// 4. Trích xuất các Cặp Số Đồng Xuất Hiện Cùng Kỳ (In-Draw Co-occurrence Pairs)
const coOccurrencePairs = [];
const keys = Object.keys(pairCooccurrence);
for (let i = 0; i < keys.length; i++) {
  const a = keys[i];
  for (let j = i + 1; j < keys.length; j++) {
    const b = keys[j];
    const cooccurCount = pairCooccurrence[a][b] || 0;
    if (cooccurCount > 0) {
      const countA = singleCounts[a] || 0;
      const countB = singleCounts[b] || 0;
      const probA = countA / nDraws;
      const probB = countB / nDraws;
      const probAB = cooccurCount / nDraws;
      const lift = (probA > 0 && probB > 0) ? (probAB / (probA * probB)) : 1.0;
      const conf = countA > 0 ? (cooccurCount / countA) : 0;
      const strA = isVietlott ? String(a).padStart(2, '0') : String(a);
      const strB = isVietlott ? String(b).padStart(2, '0') : String(b);

      coOccurrencePairs.push({
        pair: `${strA} - ${strB}`,
        a: strA,
        b: strB,
        coOccurrenceCount: cooccurCount,
        count: cooccurCount, // Hỗ trợ tương thích ngược
        totalEligibleDraws: nDraws,
        support: Math.round(probAB * 1000) / 1000,
        confidence: Math.round(conf * 1000) / 1000,
        lift: Math.round(lift * 100) / 100,
        gameType: isVietlott ? 'vietlott' : 'xsmn'
      });
    }
  }
}

// Sắp xếp ưu tiên cặp về cùng nhau nhiều nhất, sau đó theo chỉ số gắn kết Lift
coOccurrencePairs.sort((x, y) => y.coOccurrenceCount - x.coOccurrenceCount || y.lift - x.lift);
const uniqueTopPairs = coOccurrencePairs.slice(0, 10);

return {
