  // Ghi báo cáo audit artifact (nếu không set noWrite)
  if (!options.noWrite) {
    const auditReportPath = options.reportPath || path.join(__dirname, '../data/audit-report.json');
    fs.writeFileSync(auditReportPath, JSON.stringify(report, null, 2), 'utf-8');
