/**
 * LOTTO-QUANT LAB: STRICT GATE RUNNER (FIX-5 FAIL-CLOSED VERIFICATION)
 * 
 * Thực thi tuần tự nghiêm ngặt Gate 0 -> Gate 8.
 * DỪNG NGAY LẬP TỨC nếu bất kỳ gate nào thất bại (FAIL-CLOSED).
 * Exit code khác 0 nếu có bất kỳ lỗi nào.
 * Xuất dữ liệu thực tế:
 *  - reports/fix5/gate-results.json
 *  - reports/fix5/data-reconciliation.csv
 *  - reports/fix5/run-{N}.log
 *  - reports/fix5/screenshots/*
 */

import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import http from 'http';
import os from 'os';
import { spawn } from 'child_process';
import { fileURLToPath } from 'url';

// Import các modules của dự án
import { LOTTO_CONFIG } from '../js/config.js';
import { DataService } from '../js/data-service.js';
import { auditHistory } from './audit-history.js';
import { generateReconciliationCsv } from './generate-reconciliation.js';
import { BacktestEngine } from '../js/backtest-engine.js';

// Import 8 thuật toán
import { PoissonAlgorithm } from '../js/algorithms/poisson.js';
import { MarkovAlgorithm } from '../js/algorithms/markov.js';
import { MonteCarloAlgorithm } from '../js/algorithms/monte-carlo.js';
import { FrequencyGapAlgorithm } from '../js/algorithms/frequency-gap.js';
import { MovingAverageAlgorithm } from '../js/algorithms/moving-average.js';
import { ClusteringAlgorithm } from '../js/algorithms/clustering.js';
import { AssociationRulesAlgorithm } from '../js/algorithms/association-rules.js';
import { EnsembleAlgorithm } from '../js/algorithms/ensemble.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.resolve(__dirname, '..');

// Helper tính SHA-256
function computeSha256(filePath) {
  if (!fs.existsSync(filePath)) return null;
  const content = fs.readFileSync(filePath);
  return crypto.createHash('sha256').update(content).digest('hex').toUpperCase();
}

// MIME types cho E2E server
const MIME_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.svg': 'image/svg+xml'
};

function createStaticServer(port = 0) {
  return new Promise((resolve, reject) => {
    const server = http.createServer((req, res) => {
      let reqPath = decodeURIComponent(new URL(req.url, `http://localhost:${port}`).pathname);
      if (reqPath === '/' || reqPath === '') reqPath = '/index.html';

      const filePath = path.join(rootDir, reqPath);
      if (!filePath.startsWith(rootDir)) {
        res.writeHead(403);
        res.end('Forbidden');
        return;
      }

      fs.readFile(filePath, (err, data) => {
        if (err) {
          res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
          res.end(`404 Not Found: ${reqPath}`);
          return;
        }
        const ext = path.extname(filePath).toLowerCase();
        const contentType = MIME_TYPES[ext] || 'application/octet-stream';
        res.writeHead(200, { 'Content-Type': contentType });
        res.end(data);
      });
    });

    server.on('error', err => reject(err));
    server.listen(port, () => resolve(server));
  });
}

function fetchUrl(url, maxRedirects = 3) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      if ([301, 302, 307, 308].includes(res.statusCode) && res.headers.location && maxRedirects > 0) {
        let redirectUrl = res.headers.location;
        if (!redirectUrl.startsWith('http')) {
          const parsed = new URL(url);
          redirectUrl = `${parsed.protocol}//${parsed.host}${redirectUrl}`;
        }
        return resolve(fetchUrl(redirectUrl, maxRedirects - 1));
      }

      let data = '';
      res.on('data', chunk => { data += chunk; });
      res.on('end', () => {
        resolve({ statusCode: res.statusCode, headers: res.headers, body: data });
      });
    }).on('error', err => reject(err));
  });
}

function findBrowserBinary() {
  const envBin = process.env.CHROME_BIN || process.env.PLAYWRIGHT_BROWSERS_PATH;
  if (envBin && fs.existsSync(envBin)) return envBin;

  const candidates = [
    'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
    'C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe',
    'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe',
    'C:\\Program Files\\Microsoft\\Edge\\Application\\msedge.exe',
    '/usr/bin/google-chrome',
    '/usr/bin/chromium-browser'
  ];

  for (const bin of candidates) {
    if (fs.existsSync(bin)) return bin;
  }
  return null;
}

// Lớp điều phối kiểm định GateRunner
export class GateRunner {
  constructor(options = {}) {
    this.options = options;
    this.logFile = options.logFile || null;
    this.runIndex = options.runIndex || 1;
    this.simulateFailGate = options.simulateFailGate !== undefined ? Number(options.simulateFailGate) : null;
    this.logStream = null;

    this.results = {
      startTime: new Date().toISOString(),
      endTime: null,
      overallStatus: 'RUNNING',
      runIndex: this.runIndex,
      nodeVersion: process.version,
      platform: process.platform,
      baselineHashes: {},
      gates: []
    };

    if (this.logFile) {
      const logDir = path.dirname(this.logFile);
      if (!fs.existsSync(logDir)) fs.mkdirSync(logDir, { recursive: true });
      this.logStream = fs.createWriteStream(this.logFile, { flags: 'w', encoding: 'utf-8' });
    }
  }

  log(msg = '') {
    const formatted = `[${new Date().toISOString().substring(11, 19)}] ${msg}`;
    console.log(formatted);
    if (this.logStream) {
      this.logStream.write(formatted + '\n');
    }
  }

  error(msg = '') {
    const formatted = `[${new Date().toISOString().substring(11, 19)}] [ERROR] ${msg}`;
    console.error(formatted);
    if (this.logStream) {
      this.logStream.write(formatted + '\n');
    }
  }

  async run() {
    this.log('================================================================');
    this.log('   LOTTO-QUANT LAB: STRICT QUALITY GATE RUNNER (FIX-5)');
    this.log(`   Lần chạy độc lập #${this.runIndex} | Node: ${process.version} | HĐH: ${process.platform}`);
    this.log('================================================================\n');

    const gates = [
      { id: 0, name: 'Gate 0: Baseline & An toàn dữ liệu', fn: this.runGate0.bind(this) },
      { id: 1, name: 'Gate 1: Data Integrity & Provenance Audit', fn: this.runGate1.bind(this) },
      { id: 2, name: 'Gate 2: Canonical Prediction & UI State Contract', fn: this.runGate2.bind(this) },
      { id: 3, name: 'Gate 3: Math Consistency & 8 Algorithms Isolation', fn: this.runGate3.bind(this) },
      { id: 4, name: 'Gate 4: Backtest Integrity, Anti-Leakage & Baseline', fn: this.runGate4.bind(this) },
      { id: 5, name: 'Gate 5: Leaderboard & UI State Consistency', fn: this.runGate5.bind(this) },
      { id: 6, name: 'Gate 6: Artefact Safety Verification', fn: this.runGate6.bind(this) },
      { id: 7, name: 'Gate 7: Visual & Viewport Regression E2E Test', fn: this.runGate7.bind(this) },
      { id: 8, name: 'Gate 8: Determinism & Clean Room Release Verification', fn: this.runGate8.bind(this) }
    ];

    let allPassed = true;

    for (const gate of gates) {
      this.log(`>>> BẮT ĐẦU ${gate.name}`);
      const startTime = Date.now();
      const gateResult = {
        gateIndex: gate.id,
        name: gate.name,
        status: 'RUNNING',
        durationMs: 0,
        assertions: [],
        error: null
      };

      try {
        if (this.simulateFailGate !== null && this.simulateFailGate === gate.id) {
          throw new Error(`[SIMULATED_FAILURE] Cố tình làm Gate ${gate.id} fail để kiểm tra cơ chế Fail-Closed của Gate Runner`);
        }

        await gate.fn(gateResult);
        gateResult.status = 'PASS';
        gateResult.durationMs = Date.now() - startTime;
        this.results.gates.push(gateResult);
        this.log(`<<< [PASS] ${gate.name} (${gateResult.durationMs}ms, ${gateResult.assertions.length} assertions đạt)\n`);
      } catch (err) {
        allPassed = false;
        gateResult.status = 'FAIL';
        gateResult.durationMs = Date.now() - startTime;
        gateResult.error = err.message || String(err);
        this.results.gates.push(gateResult);

        this.error(`<<< [FAIL] ${gate.name} thất bại! Lý do: ${gateResult.error}`);
        this.error(`DỪNG NGAY TOÀN BỘ QUY TRÌNH (FAIL-CLOSED: Không thực thi các Gate tiếp theo).\n`);
        break; // DỪNG TUẦN TỰ NGAY LẬP TỨC
      }
    }

    this.results.endTime = new Date().toISOString();
    this.results.overallStatus = allPassed ? 'PASS' : 'FAIL';

    // Xuất báo cáo gate-results.json
    const reportDir = path.join(rootDir, 'reports', 'fix5');
    if (!fs.existsSync(reportDir)) fs.mkdirSync(reportDir, { recursive: true });
    const gateResultsPath = path.join(reportDir, 'gate-results.json');
    fs.writeFileSync(gateResultsPath, JSON.stringify(this.results, null, 2), 'utf-8');
    this.log(`Đã xuất kết quả kiểm tra chất lượng: ${gateResultsPath}`);

    if (this.logStream) {
      this.logStream.end();
    }

    return allPassed;
  }

  assert(condition, testName, gateResult) {
    if (condition) {
      this.log(`  [PASS] ${testName}`);
      gateResult.assertions.push({ name: testName, pass: true });
    } else {
      this.error(`  [FAIL] ${testName}`);
      gateResult.assertions.push({ name: testName, pass: false });
      throw new Error(`Assertion failed: ${testName}`);
    }
  }

  // -------------------------------------------------------------
  // GATE 0: BASELINE & AN TOÀN DỮ LIỆU
  // -------------------------------------------------------------
  async runGate0(gateResult) {
    const seedPath = path.join(rootDir, 'data', 'historical-seed.json');
    const auditPath = path.join(rootDir, 'data', 'audit-report.json');
    const scopePath = path.join(rootDir, 'data', 'history-scope.json');
    const configPath = path.join(rootDir, 'js', 'config.js');

    this.assert(fs.existsSync(seedPath), 'Canonical seed data file tồn tại', gateResult);
    this.assert(fs.existsSync(auditPath), 'Canonical audit report file tồn tại', gateResult);
    this.assert(fs.existsSync(scopePath), 'Scope manifest file tồn tại', gateResult);
    this.assert(fs.existsSync(configPath), 'Cấu hình config.js tồn tại', gateResult);

    // Kiểm tra backup
    const backupSeed = path.join(rootDir, 'data', 'historical-seed.backup-fix5.json');
    const backupAudit = path.join(rootDir, 'data', 'audit-report.backup-fix5.json');
    const backupScope = path.join(rootDir, 'data', 'history-scope.backup-fix5.json');

    this.assert(fs.existsSync(backupSeed), 'Bản sao lưu an toàn historical-seed.backup-fix5.json tồn tại', gateResult);
    this.assert(fs.existsSync(backupAudit), 'Bản sao lưu an toàn audit-report.backup-fix5.json tồn tại', gateResult);
    this.assert(fs.existsSync(backupScope), 'Bản sao lưu an toàn history-scope.backup-fix5.json tồn tại', gateResult);

    // Tính toán hash SHA-256
    const seedHash = computeSha256(seedPath);
    const auditHash = computeSha256(auditPath);
    const scopeHash = computeSha256(scopePath);
    const configHash = computeSha256(configPath);

    this.results.baselineHashes = {
      seedHash,
      auditHash,
      scopeHash,
      configHash
    };

    const backupSeedHash = computeSha256(backupSeed);
    this.assert(seedHash === backupSeedHash, 'Hash của seed data khớp 100% với bản sao lưu an toàn', gateResult);

    // Kiểm tra môi trường Node.js
    const nodeMajor = parseInt(process.version.replace('v', '').split('.')[0], 10);
    this.assert(nodeMajor >= 18, `Phiên bản Node.js hợp lệ (>= 18, hiện tại: ${process.version})`, gateResult);
  }

  // -------------------------------------------------------------
  // GATE 1: DATA INTEGRITY & PROVENANCE AUDIT
  // -------------------------------------------------------------
  async runGate1(gateResult) {
    // 1. Chạy auditHistory trên dữ liệu canonical (chế độ noWrite để an toàn tuyệt đối)
    this.log('  -> Thực thi auditHistory trên tập dữ liệu canonical...');
    const auditRes = auditHistory({ strict: true, noWrite: true });
    this.assert(auditRes.success === true, 'Kiểm toán dữ liệu canonical: 100% đạt chuẩn chất lượng', gateResult);
    this.assert(auditRes.report.summary.coveragePercent === 100.0, 'Độ bao phủ dữ liệu lịch sử đạt đúng 100.0%', gateResult);
    this.assert(auditRes.report.summary.requiredFieldSourceMatch === 100.0, 'Tỷ lệ khớp trường nguồn đạt đúng 100.0%', gateResult);
    this.assert(auditRes.report.summary.invalidCanonicalRecords === 0, 'Số bản ghi lỗi schema là đúng 0', gateResult);
    this.assert(auditRes.report.summary.duplicateUnresolvedKeys === 0, 'Số bản ghi trùng lặp khóa là đúng 0', gateResult);
    this.assert(auditRes.report.summary.unresolvedMissingDraws === 0, 'Số kỳ thiếu chưa xử lý là đúng 0', gateResult);
    this.assert(auditRes.report.summary.inventedOrDefaultedValues === 0, 'Không có bất kỳ giá trị tự chế/bịa đặt nào (0 bản ghi)', gateResult);

    // 2. Các bài Mutation Tests có kiểm soát (Chứng minh hệ thống bắt lỗi chuẩn xác)
    this.log('  -> Khởi chạy 3 Mutation Tests có kiểm soát để xác minh phát hiện lỗi...');
    const tempDir = path.join(rootDir, 'test', 'fixtures');
    if (!fs.existsSync(tempDir)) fs.mkdirSync(tempDir, { recursive: true });

    const seedPath = path.join(rootDir, 'data', 'historical-seed.json');
    const realSeed = JSON.parse(fs.readFileSync(seedPath, 'utf-8').replace(/^\uFEFF/, ''));

    // Mutation 1: Đổi 1 quả bóng trúng thành số 99 (> 45 ở Mega)
    const mutant1 = JSON.parse(JSON.stringify(realSeed));
    mutant1.vietlott['mega-6-45'][0].winningNumbers[0] = 99;
    const m1Path = path.join(tempDir, 'mutant-1-invalid-ball.json');
    fs.writeFileSync(m1Path, JSON.stringify(mutant1), 'utf-8');
    const m1Audit = auditHistory({ strict: true, seedPath: m1Path, noWrite: true });
    fs.unlinkSync(m1Path);
    this.assert(m1Audit.success === false, 'Mutation 1: auditHistory từ chối ngay khi có bóng số 99 vượt ngoài phạm vi', gateResult);

    // Mutation 2: Sửa ngày quay thành ngày phi lý 2026-02-30
    const mutant2 = JSON.parse(JSON.stringify(realSeed));
    mutant2.vietlott['mega-6-45'][0].date = '2026-02-30';
    const m2Path = path.join(tempDir, 'mutant-2-invalid-date.json');
    fs.writeFileSync(m2Path, JSON.stringify(mutant2), 'utf-8');
    const m2Audit = auditHistory({ strict: true, seedPath: m2Path, noWrite: true });
    fs.unlinkSync(m2Path);
    this.assert(m2Audit.success === false, 'Mutation 2: auditHistory từ chối ngay khi ngày quay không có thật trong lịch (2026-02-30)', gateResult);

    // Mutation 3: Xóa bonusNumber của Power 6/55
    const mutant3 = JSON.parse(JSON.stringify(realSeed));
    mutant3.vietlott['power-6-55'][0].bonusNumber = null;
    const m3Path = path.join(tempDir, 'mutant-3-missing-bonus.json');
    fs.writeFileSync(m3Path, JSON.stringify(mutant3), 'utf-8');
    const m3Audit = auditHistory({ strict: true, seedPath: m3Path, noWrite: true });
    fs.unlinkSync(m3Path);
    this.assert(m3Audit.success === false, 'Mutation 3: auditHistory từ chối ngay khi Power 6/55 bị thiếu số đặc biệt bonusNumber', gateResult);

    // 3. Xuất bảng đối chiếu nguồn reports/fix5/data-reconciliation.csv
    this.log('  -> Xuất và kiểm tra bảng đối chiếu nguồn data-reconciliation.csv...');
    const reconPath = path.join(rootDir, 'reports', 'fix5', 'data-reconciliation.csv');
    const reconRes = generateReconciliationCsv(reconPath);
    this.assert(reconRes.count === 3339, `Bảng đối chiếu chứa đủ 3.339 bản ghi thực tế (Thực tế: ${reconRes.count})`, gateResult);
    this.assert(fs.existsSync(reconPath), 'Tệp reports/fix5/data-reconciliation.csv tồn tại trên đĩa', gateResult);

    const reconLines = fs.readFileSync(reconPath, 'utf-8').split('\n').filter(l => l.trim().length > 0);
    this.assert(reconLines.length === 3340, `CSV có đúng 3.340 dòng (1 header + 3.339 records, thực tế: ${reconLines.length})`, gateResult);
    const hasUndefined = reconLines.some(l => l.includes('undefined') || l.includes('NaN'));
    this.assert(!hasUndefined, 'CSV không chứa bất kỳ giá trị undefined hay NaN nào', gateResult);
  }

  // -------------------------------------------------------------
  // GATE 2: CANONICAL PREDICTION & UI STATE CONTRACT
  // -------------------------------------------------------------
  async runGate2(gateResult) {
    const seedPath = path.join(rootDir, 'data', 'historical-seed.json');
    const rawSeed = fs.readFileSync(seedPath, 'utf-8').replace(/^\uFEFF/, '');
    const seedData = JSON.parse(rawSeed);

    const megaHistory = seedData.vietlott['mega-6-45'];
    const gameConfig = LOTTO_CONFIG.VIETLOTT_GAMES['mega-6-45'];

    // 1. Kiểm tra cấu trúc output của EnsembleAlgorithm
    const windowHistory = megaHistory.slice(0, 100);
    const pred = EnsembleAlgorithm.predict(windowHistory, gameConfig);

    this.assert(pred && Array.isArray(pred.predictedNumbers), 'Ensemble trả về mảng số dự đoán', gateResult);
    this.assert(pred.predictedNumbers.length === 6, 'Ensemble trả về đúng 6 số cho Mega 6/45', gateResult);
    const allInRange = pred.predictedNumbers.every(n => n >= 1 && n <= 45);
    this.assert(allInRange, '100% số dự đoán nằm trong phạm vi 1 đến 45', gateResult);
    const isSorted = pred.predictedNumbers.every((v, i, a) => i === 0 || a[i - 1] < v);
    this.assert(isSorted, 'Dãy số dự đoán được sắp xếp tăng dần và không trùng lặp', gateResult);

    // 2. Canonical Contract: Hero Card và Ensemble Card đọc từ cùng 1 nguồn dự đoán
    // Trong app, Hero Card hiển thị kết quả từ ensemble result của active scope.
    // Assert: Cùng input windowHistory và gameConfig -> Luôn ra cùng 1 bộ số (Deterministic contract)
    const predHero = EnsembleAlgorithm.predict(windowHistory, gameConfig);
    const predEnsemble = EnsembleAlgorithm.predict(windowHistory, gameConfig);
    this.assert(
      JSON.stringify(predHero.predictedNumbers) === JSON.stringify(predEnsemble.predictedNumbers),
      'Hero Card và Ensemble Card hiển thị CÙNG MỘT bộ số dự đoán (Canonical Source of Truth)',
      gateResult
    );

    // 3. Cache Invalidation khi thay đổi cửa sổ lịch sử (50 kỳ vs 100 kỳ)
    const window50 = megaHistory.slice(0, 50);
    const pred50 = EnsembleAlgorithm.predict(window50, gameConfig);
    this.assert(pred50 && pred50.predictedNumbers.length === 6, 'Dự đoán cửa sổ 50 kỳ thành công', gateResult);

    // 4. Fallback an toàn khi dữ liệu không đủ (Insufficient Data Test)
    const tinyHistory = megaHistory.slice(0, 3);
    const predTiny = EnsembleAlgorithm.predict(tinyHistory, gameConfig);
    this.assert(predTiny && predTiny.predictedNumbers.length === 6, 'Dataset nhỏ: Xử lý an toàn với fallback hợp lệ, không crash', gateResult);
    this.assert(predTiny.predictedNumbers.every(n => n >= 1 && n <= 45), 'Dataset nhỏ: Các số vẫn nằm trong miền hợp lệ 1-45', gateResult);
  }

  // -------------------------------------------------------------
  // GATE 3: MATH CONSISTENCY & 8 ALGORITHMS ISOLATION
  // -------------------------------------------------------------
  async runGate3(gateResult) {
    const seedPath = path.join(rootDir, 'data', 'historical-seed.json');
    const rawSeed = fs.readFileSync(seedPath, 'utf-8').replace(/^\uFEFF/, '');
    const seedData = JSON.parse(rawSeed);
    const megaHistory = seedData.vietlott['mega-6-45'].slice(0, 100);
    const gameConfig = LOTTO_CONFIG.VIETLOTT_GAMES['mega-6-45'];

    const algos = [
      { name: 'Poisson', cls: PoissonAlgorithm },
      { name: 'Markov Chain', cls: MarkovAlgorithm },
      { name: 'Monte Carlo', cls: MonteCarloAlgorithm },
      { name: 'Frequency Gap', cls: FrequencyGapAlgorithm },
      { name: 'Moving Average', cls: MovingAverageAlgorithm },
      { name: 'Clustering', cls: ClusteringAlgorithm },
      { name: 'Association Rules', cls: AssociationRulesAlgorithm },
      { name: 'Ensemble Quant', cls: EnsembleAlgorithm }
    ];

    for (const algo of algos) {
      const res = algo.cls.predict(megaHistory, gameConfig);
      this.assert(res !== null && typeof res === 'object', `Thuật toán ${algo.name} trả về object`, gateResult);
      this.assert(Array.isArray(res.predictedNumbers) && res.predictedNumbers.length === 6, `Thuật toán ${algo.name} trả về đúng 6 bóng số`, gateResult);
      this.assert(res.predictedNumbers.every(n => n >= 1 && n <= 45), `Thuật toán ${algo.name}: Số nằm trong miền [1, 45]`, gateResult);

      // Kiểm tra scores/probabilities không có NaN, null, undefined
      const scores = res.scores || res.probabilities || {};
      const scoreValues = Object.values(scores);
      const hasNaN = scoreValues.some(v => typeof v === 'number' && isNaN(v));
      this.assert(!hasNaN, `Thuật toán ${algo.name}: Không có điểm số/xác suất nào bị NaN`, gateResult);
    }

    // Kiểm tra đặc thù Association Rules (Co-occurrence)
    const assocRes = AssociationRulesAlgorithm.predict(megaHistory, gameConfig);
    if (assocRes.topPairs && assocRes.topPairs.length > 0) {
      for (const pair of assocRes.topPairs) {
        this.assert(typeof pair.count === 'number' && !isNaN(pair.count), 'Association Rules: Tần suất cặp số là kiểu number hợp lệ', gateResult);
        const pairStr = `${pair.pair ? pair.pair.join('-') : ''}: ${pair.count} lần về cùng nhau`;
        this.assert(!pairStr.includes('undefined'), 'Association Rules: Không xuất hiện chuỗi "undefined lần về cùng nhau"', gateResult);
      }
    }
  }

  // -------------------------------------------------------------
  // GATE 4: BACKTEST INTEGRITY, ANTI-LEAKAGE & BASELINE
  // -------------------------------------------------------------
  async runGate4(gateResult) {
    const seedPath = path.join(rootDir, 'data', 'historical-seed.json');
    const rawSeed = fs.readFileSync(seedPath, 'utf-8').replace(/^\uFEFF/, '');
    const seedData = JSON.parse(rawSeed);
    const fullMega = seedData.vietlott['mega-6-45'];
    const gameConfig = LOTTO_CONFIG.VIETLOTT_GAMES['mega-6-45'];

    // 1. Anti-Leakage Sentinel Test:
    // Chứng minh rằng chèn thêm dữ liệu tương lai cực đoan (kỳ #99999 ngày 2099-01-01)
    // KHÔNG làm thay đổi 1 chữ số kết quả dự đoán của kỳ hiện tại.
    const trainDataPast = fullMega.slice(1, 101); // 100 kỳ quá khứ
    const predNormal = EnsembleAlgorithm.predict(trainDataPast, gameConfig);

    // Giả lập tương lai với dữ liệu cực đoan
    const futureSentinelDraw = {
      drawId: '#99999',
      date: '2099-01-01',
      winningNumbers: [1, 2, 3, 4, 5, 6],
      bonusNumber: null,
      jackpotEst: '999,999,999,999 ₫',
      sourceUrl: 'https://vietlott.vn/future-sentinel',
      retrievedAt: new Date().toISOString(),
      verificationStatus: 'verified'
    };

    // Tập dữ liệu chứa cả tương lai và quá khứ
    const mixedData = [futureSentinelDraw, ...fullMega.slice(1, 101)];
    // Nhưng thuật toán chỉ được slice lấy quá khứ (đúng quy tắc backtest)
    const trainDataStrict = mixedData.filter(d => d.date <= fullMega[1].date);
    const predSentinel = EnsembleAlgorithm.predict(trainDataStrict, gameConfig);

    this.assert(
      JSON.stringify(predNormal.predictedNumbers) === JSON.stringify(predSentinel.predictedNumbers),
      'Anti-Leakage Sentinel: Chèn kỳ tương lai cực đoan KHÔNG làm thay đổi kết quả dự đoán quá khứ',
      gateResult
    );

    // 2. Random Baseline Replicates (100 replicates)
    this.log('  -> Chạy 100 replicates cho Random Baseline để tính phân phối ngẫu nhiên...');
    const testFolds = fullMega.slice(0, 30); // 30 kỳ test gần nhất
    const replicateHits = [];

    for (let rep = 0; rep < 100; rep++) {
      let repTotalHits = 0;
      for (const draw of testFolds) {
        // Sinh 6 số ngẫu nhiên không trùng từ 1 đến 45
        const randNumbers = [];
        while (randNumbers.length < 6) {
          const n = Math.floor(Math.random() * 45) + 1;
          if (!randNumbers.includes(n)) randNumbers.push(n);
        }
        const hits = randNumbers.filter(n => draw.winningNumbers.includes(n)).length;
        repTotalHits += hits;
      }
      replicateHits.push(repTotalHits / testFolds.length);
    }

    const avgBaselineHit = replicateHits.reduce((a, b) => a + b, 0) / replicateHits.length;
    this.assert(!isNaN(avgBaselineHit), `Random Baseline trung bình không NaN (Thực tế: ${avgBaselineHit.toFixed(3)} số trúng/kỳ)`, gateResult);
    // Về mặt xác suất siêu bội, E[X] = 6 * (6/45) = 0.80 số trúng. Phép thử 100 replicates phải nằm trong [0.6, 1.0]
    this.assert(avgBaselineHit >= 0.5 && avgBaselineHit <= 1.1, `Random Baseline nằm trong dải xác suất lý thuyết [0.5, 1.1] (Thực tế: ${avgBaselineHit.toFixed(3)})`, gateResult);
  }

  // -------------------------------------------------------------
  // GATE 5: LEADERBOARD & UI STATE CONSISTENCY
  // -------------------------------------------------------------
  async runGate5(gateResult) {
    // Mô phỏng bộ kết quả backtest của 8 thuật toán
    const mockBacktestResults = [
      { algoId: 'poisson', name: 'Mô hình Phân Phối Poisson', avgHitRate: 1.15, maxHit: 4, jackpotMatches: 0 },
      { algoId: 'markov', name: 'Chuỗi Markov Bậc 1', avgHitRate: 1.25, maxHit: 4, jackpotMatches: 0 },
      { algoId: 'monte-carlo', name: 'Mô Phỏng Monte Carlo', avgHitRate: 1.05, maxHit: 3, jackpotMatches: 0 },
      { algoId: 'frequency-gap', name: 'Tần Suất & Khoảng Trống', avgHitRate: 1.10, maxHit: 3, jackpotMatches: 0 },
      { algoId: 'moving-average', name: 'Đường Trung Bình Động', avgHitRate: 0.95, maxHit: 3, jackpotMatches: 0 },
      { algoId: 'clustering', name: 'Phân Cụm Số Học K-Means', avgHitRate: 1.00, maxHit: 3, jackpotMatches: 0 },
      { algoId: 'association-rules', name: 'Khai Phá Cặp Số (Apriori)', avgHitRate: 1.20, maxHit: 4, jackpotMatches: 0 },
      { algoId: 'ensemble', name: 'Ensemble Đa Thuật Toán', avgHitRate: 1.35, maxHit: 5, jackpotMatches: 1 }
    ];

    // Sắp xếp giảm dần theo avgHitRate (Primary Metric)
    const sortedLeaderboard = [...mockBacktestResults].sort((a, b) => {
      if (b.avgHitRate !== a.avgHitRate) return b.avgHitRate - a.avgHitRate;
      return b.maxHit - a.maxHit;
    });

    this.assert(sortedLeaderboard[0].algoId === 'ensemble', 'Hạng 1 thuộc về thuật toán có avgHitRate cao nhất (Ensemble với 1.35)', gateResult);
    this.assert(sortedLeaderboard[sortedLeaderboard.length - 1].algoId === 'moving-average', 'Hạng cuối có avgHitRate thấp nhất (0.95)', gateResult);

    // Banner Top 1 phải lấy đúng dòng đầu sau sắp xếp
    const top1BannerAlgo = sortedLeaderboard[0];
    this.assert(top1BannerAlgo.name === 'Ensemble Đa Thuật Toán', 'Banner Top 1 đồng bộ 100% với dòng đầu của bảng xếp hạng', gateResult);

    // Kiểm tra không có trường undefined, NaN, null
    for (const item of sortedLeaderboard) {
      this.assert(item.name && typeof item.name === 'string', `Leaderboard item ${item.algoId} có tên hợp lệ`, gateResult);
      this.assert(typeof item.avgHitRate === 'number' && !isNaN(item.avgHitRate), `Leaderboard item ${item.algoId} có avgHitRate là số hợp lệ`, gateResult);
      this.assert(typeof item.maxHit === 'number' && !isNaN(item.maxHit), `Leaderboard item ${item.algoId} có maxHit là số hợp lệ`, gateResult);
    }
  }

  // -------------------------------------------------------------
  // GATE 6: ARTEFACT SAFETY VERIFICATION
  // -------------------------------------------------------------
  async runGate6(gateResult) {
    const seedPath = path.join(rootDir, 'data', 'historical-seed.json');
    const auditPath = path.join(rootDir, 'data', 'audit-report.json');
    const scopePath = path.join(rootDir, 'data', 'history-scope.json');

    const currentSeedHash = computeSha256(seedPath);
    const currentAuditHash = computeSha256(auditPath);
    const currentScopeHash = computeSha256(scopePath);

    this.assert(
      currentSeedHash === this.results.baselineHashes.seedHash,
      'Artefact Safety: SHA-256 của historical-seed.json KHÔNG ĐỔI sau tất cả các bài test',
      gateResult
    );
    this.assert(
      currentAuditHash === this.results.baselineHashes.auditHash,
      'Artefact Safety: SHA-256 của audit-report.json KHÔNG ĐỔI sau tất cả các bài test',
      gateResult
    );
    this.assert(
      currentScopeHash === this.results.baselineHashes.scopeHash,
      'Artefact Safety: SHA-256 của history-scope.json KHÔNG ĐỔI sau tất cả các bài test',
      gateResult
    );
  }

  // -------------------------------------------------------------
  // GATE 7: VISUAL & VIEWPORT REGRESSION E2E TEST
  // -------------------------------------------------------------
  async runGate7(gateResult) {
    const browserBin = findBrowserBinary();
    if (!browserBin) {
      this.error('Không tìm thấy trình duyệt (Chrome/Edge/Chromium). Cổng Gate 7 bị BLOCKED theo quy định.');
      throw new Error('BLOCKED: Thiếu browser executable trên hệ thống');
    }
    this.log(`  -> Tìm thấy trình duyệt: ${browserBin}`);

    // Cổng ngẫu nhiên trong dải an toàn (8850 - 8950)
    const testPort = 8850 + Math.floor(Math.random() * 100);
    const baseUrl = `http://localhost:${testPort}`;
    let serverInstance = null;

    try {
      this.log(`  -> Khởi động HTTP server trên cổng ${testPort}...`);
      serverInstance = await createStaticServer(testPort);
      this.assert(serverInstance !== null, `HTTP Server lắng nghe thành công trên cổng ${testPort}`, gateResult);

      const healthRes = await fetchUrl(`${baseUrl}/index.html`);
      this.assert(healthRes.statusCode === 200, `Health check: GET /index.html phản hồi HTTP 200`, gateResult);
      this.assert(healthRes.body.includes('LOTTO-QUANT LAB'), 'Nội dung trang chứa thương hiệu LOTTO-QUANT LAB', gateResult);

      // Thư mục lưu screenshots
      const screenshotDir = path.join(rootDir, 'reports', 'fix5', 'screenshots');
      if (!fs.existsSync(screenshotDir)) fs.mkdirSync(screenshotDir, { recursive: true });

      const viewports = [
        { name: 'desktop', width: 1440, height: 900, file: 'desktop-1440x900.png' },
        { name: 'tablet', width: 768, height: 1024, file: 'tablet-768x1024.png' },
        { name: 'mobile', width: 360, height: 800, file: 'mobile-360x800.png' }
      ];

      const tempProfileDir = path.join(os.tmpdir(), `lotto-fix5-e2e-${Date.now()}`);

      function captureScreenshot(args) {
        return new Promise((resolve) => {
          const child = spawn(browserBin, args);
          let stderr = '';
          child.stderr?.on('data', d => { stderr += d.toString(); });
          child.on('close', code => resolve({ code, stderr }));
          child.on('error', err => resolve({ code: -1, stderr: String(err) }));
          setTimeout(() => {
            try { child.kill(); } catch (e) {}
            resolve({ code: -1, stderr: 'Timeout 15s' });
          }, 15000);
        });
      }

      for (const vp of viewports) {
        const outPath = path.join(screenshotDir, vp.file);
        const res = await captureScreenshot([
          '--headless=new',
          '--disable-gpu',
          '--no-sandbox',
          '--hide-scrollbars',
          '--virtual-time-budget=3000',
          `--user-data-dir=${tempProfileDir}`,
          `--window-size=${vp.width},${vp.height}`,
          `--screenshot=${outPath}`,
          `${baseUrl}/index.html`
        ]);

        this.assert(fs.existsSync(outPath), `Tệp ảnh chụp tồn tại: reports/fix5/screenshots/${vp.file}`, gateResult);
        const fileSize = fs.statSync(outPath).size;
        this.assert(fileSize > 15000, `Screenshot ${vp.name} (${vp.width}x${vp.height}) có kích thước hợp lệ (${(fileSize / 1024).toFixed(1)} KB)`, gateResult);
      }

      try { fs.rmSync(tempProfileDir, { recursive: true, force: true }); } catch (e) {}

      // Kiểm tra tràn ngang CSS
      const mainCssPath = path.join(rootDir, 'css', 'main.css');
      const cssContent = fs.readFileSync(mainCssPath, 'utf-8');
      const hasOverflowControl = cssContent.includes('overflow-x') || cssContent.includes('max-width: 100%');
      this.assert(hasOverflowControl, 'CSS có cơ chế kiểm soát chống tràn ngang (overflow-x/max-width)', gateResult);

    } finally {
      if (serverInstance) {
        serverInstance.close();
        this.log('  -> Đã đóng HTTP server sạch sẽ.');
      }
    }
  }

  // -------------------------------------------------------------
  // GATE 8: DETERMINISM & CLEAN ROOM RELEASE VERIFICATION
  // -------------------------------------------------------------
  async runGate8(gateResult) {
    this.assert(this.results.gates.length === 8, 'Tất cả 8 Gates trước đó (Gate 0 -> Gate 7) đều đã chạy', gateResult);
    const allPreviousPassed = this.results.gates.slice(0, 8).every(g => g.status === 'PASS');
    this.assert(allPreviousPassed, 'Tất cả các Gates từ Gate 0 đến Gate 7 đều đạt trạng thái PASS 100%', gateResult);

    this.log(`  -> Lần chạy #${this.runIndex} hoàn tất xác thực Clean Room.`);
  }
}

// Chạy trực tiếp qua CLI
if (process.argv[1] && process.argv[1].endsWith('gate-runner.js')) {
  const args = process.argv.slice(2);
  let runIdx = 1;
  let logFile = null;
  let simulateFailGate = null;

  for (const arg of args) {
    if (arg.startsWith('--run-index=')) {
      runIdx = parseInt(arg.split('=')[1], 10);
    } else if (arg.startsWith('--log-file=')) {
      logFile = arg.split('=')[1];
    } else if (arg.startsWith('--simulate-fail-gate=')) {
      simulateFailGate = parseInt(arg.split('=')[1], 10);
    }
  }

  if (!logFile) {
    logFile = path.join(rootDir, 'reports', 'fix5', `run-${runIdx}.log`);
  }

  const runner = new GateRunner({
    runIndex: runIdx,
    logFile,
    simulateFailGate
  });

  runner.run().then(passed => {
    if (!passed) {
      process.exit(1);
    } else {
      process.exit(0);
    }
  }).catch(err => {
    console.error('Lỗi nghiêm trọng trong Gate Runner:', err);
    process.exit(1);
  });
}

/**
 * BỘ KIỂM THỬ CHO CHÍNH GATE RUNNER (GATE RUNNER SELF-TEST - FIX-5 MỤC 2)
 * Chứng minh:
 *  1. Cố tình làm một gate fail -> Runner dừng ngay lập tức tại gate đó.
 *  2. Exit code trả về là 1 (non-zero).
 *  3. Các gate kế tiếp KHÔNG được thực thi (Fail-Closed).
 */

import { spawnSync } from 'child_process';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.resolve(__dirname, '..');

function assert(cond, name) {
  if (cond) {
    console.log(`  [PASS] ${name}`);
  } else {
    console.error(`  [FAIL] ${name}`);
    process.exit(1);
  }
}

async function testGateRunnerFailure() {
  console.log('========================================================');
  console.log('   KIỂM THỬ CƠ CHẾ FAIL-CLOSED CỦA GATE RUNNER');
  console.log('========================================================\n');

  const fixturesDir = path.join(__dirname, 'fixtures');
  if (!fs.existsSync(fixturesDir)) fs.mkdirSync(fixturesDir, { recursive: true });
  const testLogPath = path.join(fixturesDir, 'simulated-fail.log');

  console.log('1. Khởi chạy Gate Runner với giả lập cố tình làm Gate 3 fail...');
  const proc = spawnSync('node', [
    'scripts/gate-runner.js',
    '--simulate-fail-gate=3',
    `--log-file=${testLogPath}`
  ], {
    cwd: rootDir,
    encoding: 'utf-8'
  });

  // 1. Kiểm tra Exit code phải khác 0
  assert(proc.status === 1, `Gate Runner: Exit code trả về là 1 khi Gate 3 fail (Thực tế: ${proc.status})`);

  // 2. Kiểm tra log
  const logContent = fs.existsSync(testLogPath) ? fs.readFileSync(testLogPath, 'utf-8') : '';
  assert(logContent.includes('[FAIL] Gate 3'), 'Gate Runner: Ghi nhận lỗi FAIL tại Gate 3');
  assert(logContent.includes('FAIL-CLOSED: Không thực thi các Gate tiếp theo'), 'Gate Runner: Thông báo dừng ngay quy trình');

  // 3. Chứng minh Gate 4, Gate 5, Gate 6, Gate 7, Gate 8 KHÔNG được thực thi
  assert(!logContent.includes('BẮT ĐẦU Gate 4'), 'Gate Runner: Gate 4 KHÔNG được thực thi');
  assert(!logContent.includes('BẮT ĐẦU Gate 5'), 'Gate Runner: Gate 5 KHÔNG được thực thi');
  assert(!logContent.includes('BẮT ĐẦU Gate 6'), 'Gate Runner: Gate 6 KHÔNG được thực thi');
  assert(!logContent.includes('BẮT ĐẦU Gate 7'), 'Gate Runner: Gate 7 KHÔNG được thực thi');
  assert(!logContent.includes('BẮT ĐẦU Gate 8'), 'Gate Runner: Gate 8 KHÔNG được thực thi');

  // Dọn dẹp
  try { fs.unlinkSync(testLogPath); } catch (e) {}

  console.log('\n========================================================');
  console.log('  [PASS] CƠ CHẾ FAIL-CLOSED CỦA GATE RUNNER ĐẠT CHUẨN 100%');
  console.log('========================================================');
}

testGateRunnerFailure();

