  this.log(`  -> Chụp ảnh viewport ${vp.name}...`);
  try {
    const res = await captureScreenshot([
      '--headless=new',
      '--disable-gpu',
      '--no-sandbox',
      '--hide-scrollbars',
      '--disable-extensions',
      '--disable-background-networking',
