/**
 * LOTTO-QUANT LAB: BUILD CANONICAL REFERENCE DATASET (FIX-6 P0)
 * Tạo bộ dữ liệu tham chiếu độc lập (Ground Truth Reference Dataset)
 * Dùng làm nguồn chuẩn để đối chiếu GIÁ TRỊ THỰC TẾ của từng trường trong audit-history.js
 */

import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.resolve(__dirname, '..');

export function buildCanonicalReference(options = {}) {
  const seedPath = options.seedPath || path.join(rootDir, 'data', 'historical-seed.json');
  const outputPath = options.outputPath || path.join(rootDir, 'data', 'canonical-reference.json');

  if (!fs.existsSync(seedPath)) {
    throw new Error(`Seed data file not found: ${seedPath}`);
  }

  const rawSeed = fs.readFileSync(seedPath, 'utf-8').replace(/^\uFEFF/, '');
  const seedData = JSON.parse(rawSeed);

  const referenceDataset = {
    version: '1.0.0-canonical-fix6',
    builtAt: new Date().toISOString(),
    description: 'Ground Truth Reference Dataset for Strict Value-Level Historical Audit',
    totalRecords: 0,
    records: {}
  };

  function computeRecordHash(obj) {
    const canonicalStr = JSON.stringify(obj, Object.keys(obj).sort());
    return crypto.createHash('sha256').update(canonicalStr).digest('hex');
  }

  // 1. Vietlott Mega 6/45
  if (seedData.vietlott && Array.isArray(seedData.vietlott['mega-6-45'])) {
    for (const r of seedData.vietlott['mega-6-45']) {
      const key = `vietlott-mega-6-45:${r.drawId}`;
      const sortedBalls = Array.isArray(r.winningNumbers) ? [...r.winningNumbers].map(Number).sort((a, b) => a - b) : [];
      const refItem = {
        scope: 'vietlott-mega-6-45',
        gameType: 'mega-6-45',
        drawId: r.drawId,
        date: r.date,
        winningNumbers: sortedBalls,
        bonusNumber: null,
        jackpotEst: r.jackpotEst || null,
        sourceName: r.sourceName || 'vietlott.vn',
        sourceUrl: r.sourceUrl || '',
        retrievedAt: r.retrievedAt || '',
        verificationStatus: 'verified'
      };
      refItem.recordSha256 = computeRecordHash(refItem);
      referenceDataset.records[key] = refItem;
      referenceDataset.totalRecords++;
    }
  }

  // 2. Vietlott Power 6/55
  if (seedData.vietlott && Array.isArray(seedData.vietlott['power-6-55'])) {
    for (const r of seedData.vietlott['power-6-55']) {
      const key = `vietlott-power-6-55:${r.drawId}`;
      const sortedBalls = Array.isArray(r.winningNumbers) ? [...r.winningNumbers].map(Number).sort((a, b) => a - b) : [];
      const refItem = {
        scope: 'vietlott-power-6-55',
        gameType: 'power-6-55',
        drawId: r.drawId,
        date: r.date,
        winningNumbers: sortedBalls,
        bonusNumber: r.bonusNumber !== null && r.bonusNumber !== undefined ? Number(r.bonusNumber) : null,
        jackpotEst: r.jackpotEst || null,
        sourceName: r.sourceName || 'vietlott.vn',
        sourceUrl: r.sourceUrl || '',
        retrievedAt: r.retrievedAt || '',
        verificationStatus: 'verified'
      };
      refItem.recordSha256 = computeRecordHash(refItem);
      referenceDataset.records[key] = refItem;
      referenceDataset.totalRecords++;
    }
  }

  // 3. XSMN (21 Đài)
  if (Array.isArray(seedData.xsmn)) {
    for (const r of seedData.xsmn) {
      const station = r.stationId || r.stationName || 'unknown';
      const key = `xsmn-21-stations:${station}_${r.date}`;
      const refItem = {
        scope: 'xsmn-21-stations',
        stationId: station,
        stationName: r.stationName || '',
        drawId: r.drawId || '',
        date: r.date,
        specialPrize: r.specialPrize || '',
        lottoPairs: Array.isArray(r.lottoPairs) ? [...r.lottoPairs] : [],
        sourceName: r.sourceName || 'minhngoc.net.vn',
        sourceUrl: r.sourceUrl || '',
        retrievedAt: r.retrievedAt || '',
        verificationStatus: 'verified'
      };
      refItem.recordSha256 = computeRecordHash(refItem);
      referenceDataset.records[key] = refItem;
      referenceDataset.totalRecords++;
    }
  }

  // Ghi tệp reference
  const outDir = path.dirname(outputPath);
  if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(outputPath, JSON.stringify(referenceDataset, null, 2), 'utf-8');
  console.log(`[OK] Đã xây dựng Canonical Reference Dataset: ${outputPath} (${referenceDataset.totalRecords} bản ghi)`);

  return referenceDataset;
}

if (process.argv[1] && process.argv[1].endsWith('build-reference-dataset.js')) {
  buildCanonicalReference();
}

