  async runGateB(gateResult) {
    this.log('  -> Thực thi Value-Level Strict Audit trên dữ liệu canonical...');
    const auditRes = auditHistory({ strict: true, noWrite: true });
    this.assert(auditRes.success === true, 'Kiểm toán dữ liệu canonical: 100% đạt chuẩn chất lượng', gateResult);
    this.assert(auditRes.report.summary.coveragePercent === 100.0, 'Độ bao phủ dữ liệu lịch sử đạt đúng 100.0%', gateResult);
    this.assert(auditRes.report.summary.requiredFieldSourceMatch === 100.0, 'Tỷ lệ khớp trường nguồn đạt đúng 100.0%', gateResult);
    this.assert(auditRes.report.summary.invalidCanonicalRecords === 0, 'Số bản ghi lỗi schema là đúng 0', gateResult);
    this.assert(auditRes.report.summary.duplicateUnresolvedKeys === 0, 'Số bản ghi trùng lặp khóa là đúng 0', gateResult);
    this.assert(auditRes.report.summary.unresolvedMissingDraws === 0, 'Số kỳ thiếu chưa xử lý là đúng 0', gateResult);
    this.assert(auditRes.report.summary.inventedOrDefaultedValues === 0, 'Không có giá trị tự chế/bịa đặt nào (0 bản ghi)', gateResult);
    this.assert(auditRes.report.summary.mismatchedFields === 0, 'Số trường lệch giá trị thực tế với canonical reference là đúng 0', gateResult);

    // 4 Mutation Tests có kiểm soát
    this.log('  -> Chạy 4 Mutation Tests để chứng minh hệ thống phát hiện lỗi sai lệch giá trị...');
    const tempDir = path.join(rootDir, 'test', 'fixtures');
    if (!fs.existsSync(tempDir)) fs.mkdirSync(tempDir, { recursive: true });

    const seedPath = path.join(rootDir, 'data', 'historical-seed.json');
    const realSeed = JSON.parse(fs.readFileSync(seedPath, 'utf-8').replace(/^\uFEFF/, ''));

    // Mutation 1: Sửa 1 quả bóng thành 99 (> 45 ở Mega)
    const m1 = JSON.parse(JSON.stringify(realSeed));
    m1.vietlott['mega-6-45'][0].winningNumbers[0] = 99;
    const m1Path = path.join(tempDir, 'm1-out-of-range.json');
    fs.writeFileSync(m1Path, JSON.stringify(m1), 'utf-8');
    const m1Res = auditHistory({ strict: true, seedPath: m1Path, noWrite: true });
    try { fs.unlinkSync(m1Path); } catch (e) {}
    this.assert(m1Res.success === false, 'Mutation 1: Phát hiện và từ chối bóng 99 vượt biên [1, 45]', gateResult);

    // Mutation 2: Sửa 1 quả bóng từ 9 thành 8 (lệch giá trị thực tế với reference)
    const m2 = JSON.parse(JSON.stringify(realSeed));
    const origBall = m2.vietlott['mega-6-45'][0].winningNumbers[1];
    m2.vietlott['mega-6-45'][0].winningNumbers[1] = origBall === 8 ? 7 : 8;
    const m2Path = path.join(tempDir, 'm2-value-mismatch.json');
    fs.writeFileSync(m2Path, JSON.stringify(m2), 'utf-8');
    const m2Res = auditHistory({ strict: true, seedPath: m2Path, noWrite: true });
    try { fs.unlinkSync(m2Path); } catch (e) {}
    this.assert(m2Res.success === false && m2Res.report.summary.mismatchedFields > 0, 'Mutation 2: Phát hiện sai lệch giá trị quả bóng thực tế so với Reference Dataset', gateResult);

    // Mutation 3: Sửa ngày quay thành ngày phi lý 2026-02-30
    const m3 = JSON.parse(JSON.stringify(realSeed));
    m3.vietlott['mega-6-45'][0].date = '2026-02-30';
    const m3Path = path.join(tempDir, 'm3-invalid-date.json');
    fs.writeFileSync(m3Path, JSON.stringify(m3), 'utf-8');
    const m3Res = auditHistory({ strict: true, seedPath: m3Path, noWrite: true });
    try { fs.unlinkSync(m3Path); } catch (e) {}
    this.assert(m3Res.success === false, 'Mutation 3: Phát hiện ngày quay phi lý không có trong lịch (2026-02-30)', gateResult);

    // Mutation 4: Xóa bonusNumber của Power 6/55
    const m4 = JSON.parse(JSON.stringify(realSeed));
    m4.vietlott['power-6-55'][0].bonusNumber = null;
    const m4Path = path.join(tempDir, 'm4-missing-bonus.json');
    fs.writeFileSync(m4Path, JSON.stringify(m4), 'utf-8');
    const m4Res = auditHistory({ strict: true, seedPath: m4Path, noWrite: true });
    try { fs.unlinkSync(m4Path); } catch (e) {}
    this.assert(m4Res.success === false, 'Mutation 4: Phát hiện Power 6/55 bị thiếu số đặc biệt bonusNumber', gateResult);

    // Xuất CSV đối chiếu nguồn
    const reconPath = path.join(this.reportDir, 'data-reconciliation.csv');
    const reconRes = generateReconciliationCsv(reconPath);
    this.assert(reconRes.count === 3339, `Bảng đối chiếu chứa đủ 3.339 bản ghi thực tế (Thực tế: ${reconRes.count})`, gateResult);
    this.assert(fs.existsSync(reconPath), 'Tệp reports/fix6/data-reconciliation.csv tồn tại trên đĩa', gateResult);

    const reconLines = fs.readFileSync(reconPath, 'utf-8').split('\n').filter(l => l.trim().length > 0);
    this.assert(reconLines.length === 3340, `CSV có đúng 3.340 dòng (1 header + 3.339 records, thực tế: ${reconLines.length})`, gateResult);
    const hasUndefined = reconLines.some(l => l.includes('undefined') || l.includes('NaN'));
    this.assert(!hasUndefined, 'CSV không chứa bất kỳ giá trị undefined hay NaN nào', gateResult);
  }

