  // -------------------------------------------------------------
  async runGateJ(gateResult) {
    this.log('  -> Thực hiện Runner Self-Tests chứng minh nguyên tắc Fail-Closed...');

    // 1. Thử ép Gate B fail trên instance giả lập
    const simRunner = new GateRunner({
      runIndex: 999,
      simulateFailGate: 'B',
      isSubRun: true
    });
    const simPassed = await simRunner.run();
    this.assert(simPassed === false, 'Runner Self-Test 1: Khi Gate B fail, runner trả về false ngay lập tức', gateResult);

    // Kiểm tra các gate sau Gate B có trạng thái NOT_RUN
    const gateCResult = simRunner.results.gates.find(g => g.gateId === 'C');
    this.assert(gateCResult && gateCResult.status === 'NOT_RUN', 'Runner Self-Test 2: Gate C có trạng thái NOT_RUN khi Gate B bị lỗi (Fail-Closed bảo toàn)', gateResult);

    // 2. Thử nghiệm Artifact Safety: Kiểm tra hash không đổi
    const seedPath = path.join(rootDir, 'data', 'historical-seed.json');
    const hashNow = computeSha256(seedPath);
    this.assert(hashNow === this.results.baselineHashes.seedHash, 'Runner Self-Test 3: Dữ liệu canonical không bị ô nhiễm trong quá trình self-test', gateResult);
  }

  // -------------------------------------------------------------
