      const subLogFile = path.join(this.reportDir, `run-${r}.log`);
      const subRunner = new GateRunner({
        runIndex: r,
        logFile: subLogFile,
        reportDir: this.reportDir,
        isSubRun: true
      });

      const pass = await subRunner.run();
      this.assert(pass === true, `Lượt chạy #${r}/3 hoàn thành 100% PASS (Exit code 0)`, gateResult);

      const logHash = computeSha256(subLogFile);
      this.assert(logHash !== null, `Lượt chạy #${r}/3 đã sinh file log hợp lệ (${path.basename(subLogFile)})`, gateResult);
      runLogs.push({ runIndex: r, logFile: subLogFile, logHash });
