// scripts/export-conversation-history.js
const fs = require('fs');
const readline = require('readline');

async function processTranscript(inputFilePath, outputFilePath) {
    const fileStream = fs.createReadStream(inputFilePath, { encoding: 'utf8' });
    const rl = readline.createInterface({
        input: fileStream,
        crlfDelay: Infinity, // To recognize all instances of CR LF
    });

    let conversationHistory = "";
    let currentTurn = { userRequest: "", agentThoughts: "", agentResponse: "" };
    let inAgentThoughts = false; // Flag to track when we're inside agent thoughts
    let inAgentResponse = false; // Flag to track when agent is responding
    let turnCount = 0; // Track turn number, use it in headings.

    for await (const line of rl) {
        if (line.includes("<USER_REQUEST>")) {
            if (currentTurn.userRequest) { // If there's a previous turn, write it
              conversationHistory += renderTurn(currentTurn, turnCount);
              turnCount++;
            }
            // Start a new turn
            currentTurn = { userRequest: "", agentThoughts: "", agentResponse: "" };
            currentTurn.userRequest = line.replace("<USER_REQUEST>", "").trim();
            inAgentThoughts = false;  // Reset flags at the start of each turn
            inAgentResponse = false;
        } else if (line.includes("<AGENT_THOUGHTS>")) {
            inAgentThoughts = true;
        } else if (line.includes("<AGENT_RESPONSE>")) {
            inAgentThoughts = false;
            inAgentResponse = true;
        } else if (line.includes("</AGENT_THOUGHTS>")) {
            inAgentThoughts = false;
        } else if (line.includes("</AGENT_RESPONSE>")) {
            inAgentResponse = false;
        } else if (inAgentThoughts) {
            currentTurn.agentThoughts += line.trim() + "\n";
        } else if (inAgentResponse) {
            currentTurn.agentResponse += line.trim() + "\n";
        }
    }
    // Write the last turn
    if (currentTurn.userRequest) {
      conversationHistory += renderTurn(currentTurn, turnCount);
    }
    fs.writeFileSync(outputFilePath, conversationHistory);
}

function renderTurn(turn, turnCount) {
  let output = `\n## Turn ${turnCount + 1}\n\n`; // Add turn number

  if (turn.userRequest) {
    output += `**User:** ${turn.userRequest}\n\n`;
  }
  if (turn.agentThoughts) {
    //  output += "**Agent Thoughts:**\n";
    //  output += "```\n"
     output += turn.agentThoughts.trim() + "\n\n";
    //  output += "```\n";
  }
    if (turn.agentResponse) {
      output += "**Agent Response:**\n";
      output += turn.agentResponse.trim() + "\n\n";
  }
  return output;
}

// Main execution
const inputFilePath = 'transcript_full.jsonl';
